import { useMutation } from '@tanstack/react-query';
import { useHttpClient } from '@castify/record-mv3/common';
import { environment } from '@castify/record-mv3/environment';

interface GetContentVideoExternalUrlParams {
  videoId: string;
  urlType?: string;
}

export function useContentVideoExternalUrl() {
  const httpClient = useHttpClient();

  return useMutation<string, Error, GetContentVideoExternalUrlParams>(
    async ({ videoId, urlType }: GetContentVideoExternalUrlParams) => {
      const result = await httpClient.get<string>(
        `${environment.contentServiceUrl}/videos/${videoId}/externalUrl`,
        {
          params: {
            type: urlType === 'upload' ? 'upload' : 'download',
          },
        },
      );

      return result.data;
    },
  );
}
