import { Instance, types } from 'mobx-state-tree';

export const UserState = types
  .model('UserState', {
    /** @private access `videoLimit` to get this value instead. */
    userCastLimit: types.maybe(types.number), // -1 for unlimited
    /** @private access `castVideoCount` to get this value instead. */
    userCastCount: types.maybe(types.number),
    /** @private access `isStudentUser` to get this value instead. */
    isStudent: types.maybe(types.boolean),
    /** @private access `videoLengthLimit` to get this value instead. */
    userCastLengthLimit: types.maybe(types.number),
    activeOrgId: '',
  })
  .views((self) => {
    return {
      /** Indicates if there is valid user data in local storage. */
      get hasUserData() {
        return (
          typeof self.userCastCount === 'number' &&
          typeof self.userCastLimit === 'number' &&
          typeof self.isStudent === 'boolean' &&
          typeof self.userCastLengthLimit === 'number'
        );
      },
      /** Expected to return `false` when user data unavailable. */
      get isStudentUser() {
        return self.isStudent ?? false;
      },
      /** Expected to return `true` when user data unavailable. */
      get isFreeUser() {
        return self.userCastLimit !== -1;
      },
      get isStarterUser() {
        return self.userCastLimit === -1 && self.userCastLengthLimit === 60;
      },
      /** Expected to return `false` when user data unavailable. */
      get isProUser() {
        return self.userCastLimit === -1 && self.userCastLengthLimit === 120;
      },
      /** Expected to return `0` when user data unavailable. */
      get castVideoCount() {
        return self.userCastCount ?? 0;
      },
      /** Expected to return `0` when user data unavailable. */
      get videoLimit(): number {
        return this.hasUserData
          ? self.userCastLimit === -1
            ? Infinity
            : Number(self.userCastLimit)
          : 0;
      },
      /** Expected to return `-1` when user data unavailable. */
      get videoLengthLimit(): number {
        return self.userCastLengthLimit ?? -1;
      },
    };
  })
  .actions((self) => {
    return {
      setUserCastCount(count: number) {
        self.userCastCount = count;
      },
      setUserCastLimit(limit: number) {
        self.userCastLimit = limit;
      },
      setIsStudent(isStudent: boolean) {
        self.isStudent = isStudent;
      },
      setUserCastLengthLimit(limit: number) {
        self.userCastLengthLimit = limit;
      },
      setActiveOrgId(activeOrgId: string) {
        self.activeOrgId = activeOrgId;
      },
    };
  });

export type IUserState = Instance<typeof UserState>;
