import { useState } from 'react';
import { observer } from 'mobx-react-lite';
import Box from '@mui/material/Box';
import Drawer from '@mui/material/Drawer';
import IconButton from '@mui/material/IconButton';
import SettingsIcon from '@mui/icons-material/SettingsRounded';
import Stack from '@mui/material/Stack';
import Tooltip from '@mui/material/Tooltip';
import Typography from '@mui/material/Typography';
import ChevronRightIcon from '@mui/icons-material/ChevronRightRounded';
import { ResizeTabSelect } from './components/ResizeTabSelect';
import { LimitResolutionSelect } from './components/LimitResolutionSelect';
import { MaxFrameRateSelect } from './components/MaxFrameRateSelect';
import { AutoStopSelect } from './components/AutoStopSelect';
import { useControllerState } from '../../state/ControllerStateProvider';

/**
 * The settings menu that slides in from the right side of the extension when
 * you click the gear icon in the top right corner of the toolbar.
 */
export const RightSettingsDrawer = observer(() => {
  const [isOpen, setIsOpen] = useState(false);

  const { recordingSettings, userState } = useControllerState();

  return (
    <>
      <Tooltip title="Settings" placement="bottom">
        <IconButton
          color="info"
          size="small"
          sx={{ padding: '4px' }}
          data-testid="control-panel-header-settings"
          onClick={() => setIsOpen(true)}
        >
          <SettingsIcon />
        </IconButton>
      </Tooltip>

      <Drawer
        container={document.body}
        anchor="right"
        open={isOpen}
        onClose={() => setIsOpen(false)}
        PaperProps={{ sx: { width: '88%' } }}
      >
        <Box
          height="55px"
          width="100%"
          display="flex"
          alignItems="center"
          gap="8px"
        >
          <IconButton onClick={() => setIsOpen(false)}>
            <ChevronRightIcon />
          </IconButton>
          <Typography variant="h5">Advanced Settings</Typography>
        </Box>
        <Stack
          gap="16px"
          paddingX="16px"
          paddingBottom="16px"
          boxSizing="border-box"
        >
          <Stack direction="row" alignItems="center" gap="16px">
            <Typography width="66%">Resize tab</Typography>
            <ResizeTabSelect />
          </Stack>
          <Stack direction="row" alignItems="center" gap="16px">
            <Typography width="66%">Limit resolution</Typography>
            <LimitResolutionSelect
              selectedResolution={recordingSettings.selectedResolution}
              setSelectedResolution={recordingSettings.setSelectedResolution}
              recordMaxResolutionEnabled={
                recordingSettings.recordMaxResolutionEnabled
              }
            />
          </Stack>
          <Stack direction="row" alignItems="center" gap="16px">
            <Typography width="66%">Max frame rate</Typography>
            <MaxFrameRateSelect
              selectedFrameRate={recordingSettings.selectedFrameRate}
              setSelectedFrameRate={recordingSettings.setSelectedFrameRate}
            />
          </Stack>
          <Stack direction="row" alignItems="center" gap="16px">
            <Typography width="66%">Auto-stop</Typography>
            <AutoStopSelect
              autoStopTime={recordingSettings.autoStopTime}
              setAutoStopTime={recordingSettings.setAutoStopTime}
              isFreeUser={userState.isFreeUser}
            />
          </Stack>
        </Stack>
      </Drawer>
    </>
  );
});
