import { RecordingType } from '@castify/record-mv3/common';
import { useTeleprompterStore } from '@castify/record-mv3/common/stores';

export type DraftRecordingType = 'tab' | 'desktop' | 'teleprompter' | 'webcam';

export const getDraftRecordingType = (
  type: RecordingType,
): DraftRecordingType | null => {
  const useTeleprompter = useTeleprompterStore.getState().useTeleprompter;
  if (type === 'camera') return useTeleprompter ? 'teleprompter' : 'webcam';
  return ['tab', 'desktop'].includes(type) ? type : null;
};
