import { environment } from '@castify/record-mv3/environment';
import { initializeApp } from 'firebase/app';
import {
  getRemoteConfig,
  fetchAndActivate,
  getBoolean,
} from 'firebase/remote-config';
import { useEffect, useState } from 'react';

const firebaseApp = initializeApp(environment.firebaseConfig);

export const getUseQuickRecordFflag = async () => {
  try {
    const remoteConfig = getRemoteConfig(firebaseApp);
    remoteConfig.settings = {
      minimumFetchIntervalMillis: 0, // no cache
      fetchTimeoutMillis: 600000,
    };
    await fetchAndActivate(remoteConfig);
    return getBoolean(remoteConfig, 'useQuickRecord');
  } catch (error) {
    return false;
  }
};

export const useQuickRecordFflag = () => {
  const [useQuickRecord, setUseQuickRecord] = useState(false);

  useEffect(() => {
    const fetchFlag = async () => {
      const flagValue = await getUseQuickRecordFflag();
      setUseQuickRecord(flagValue);
    };

    fetchFlag();
  }, []);

  return useQuickRecord;
};
