import { v4 as uuidv4 } from 'uuid';
import { GDriveMetadata } from '@castify/record-mv3/record-components';

export interface CreateMetadataParams {
  videoTitle: string;
  driveFileId: string;
  duration: number;
}

export const createGoogleDriveMetadata = ({
  videoTitle,
  driveFileId,
  duration,
}: CreateMetadataParams): GDriveMetadata => ({
  title: videoTitle,
  name: videoTitle,
  description: '',
  id: driveFileId,
  mimeType: 'video/webm',
  properties: [
    {
      key: 'isScreencastifySyncFile',
      visibility: 'PRIVATE',
      value: true,
    },
    {
      key: 'uuid',
      visibility: 'PRIVATE',
      value: uuidv4(),
    },
    {
      key: 'recordingDate',
      visibility: 'PRIVATE',
      value: Date.now(),
    },
    {
      key: 'duration',
      visibility: 'PRIVATE',
      value: duration,
    },
  ],
});
