import { initialize, TextCapture } from '@pendo/agent';
import pendoConfig from './pendo.config.json';

const ACCOUNT_ID = 'screencastify-mv3';
const VISITOR_ID = '[id not available]';
const NAME = '[name not available]';
const EMAIL = '[email not available]';
const ROLE = '[user type not available]';

interface InitPendoProps {
  visitorId?: string | null;
  name?: string | null;
  email?: string | null;
  role?: string | null;
}

export const initPendo = async ({
  visitorId = VISITOR_ID,
  name = NAME,
  email = EMAIL,
  role = ROLE,
}: InitPendoProps) => {
  const pendo = await initialize({
    apiKey: pendoConfig.apiKey,
    env: 'io',
    visitor: {
      id: visitorId,
      name,
      email,
      role,
    },
    account: { id: ACCOUNT_ID },
    globalKey: 'pendo',
    plugins: [TextCapture],
    config: pendoConfig,
    assets: {
      host: chrome.runtime.getURL('').slice(0, -1),
      path: 'assets/pendo',
      localOnly: true,
    },
  });

  return pendo;
};
