import { environment } from '@castify/record-mv3/environment';
import { createBrowserLogger } from '@cfy/fe-monitoring';

const logger = createBrowserLogger('localVideoTabInjection');

/** @throws {Error} Will throw an error if the tab could not be created. */
export const openTabToLocalVideo = async (
  videoRegistryId: string,
  searchParams?: URLSearchParams,
): Promise<chrome.tabs.Tab> => {
  const url = new URL(
    environment.externalLinks.manageVideoPage +
      `/${videoRegistryId}` +
      (searchParams ? `?${searchParams.toString()}` : ''),
  );
  const tab = await chrome.tabs.create({ active: true, url: url.href });
  return tab;
};

export const injectLocalVideoToTab = (
  tab: chrome.tabs.Tab,
  blobURL: string,
) => {
  if (!tab.id) {
    logger.error(
      `Could not inject script into tab with no ID: ${JSON.stringify(tab)}`,
    );
    return;
  }
  chrome.scripting.executeScript({
    target: { tabId: tab.id },
    args: [blobURL, environment.externalLinks.manageVideoPage],
    func: injectLocalVideo,
  });
};

/** @throws {Error} Will throw an error if the tab could not be created. */
export const openTabAndInjectLocalVideo = async (
  videoRegistryId: string,
  blobURL: string,
): Promise<void> => {
  try {
    const tab = await openTabToLocalVideo(videoRegistryId);
    injectLocalVideoToTab(tab, blobURL);
  } catch (error) {
    logger.error((error as Error).message);
    throw Error(
      `Failed to open tab for video with videoRegistryId ${videoRegistryId}`,
    );
  }
};

/**
 * A script to inject a video from the extension's IndexedDB into a browser tab.
 * By saving a blob URL of it in local storage, you can watch it before it finishes
 * uploading by using it as the source of the video player.
 *
 * Caveat:
 * The VMP only seems capable of loading the video this way if the video was injected after page load.
 * After refresing the page, attempting to load the same video from local storage results in a 404.
 * This is due to how ObjectURL memory management is handled by the browser.
 * The lesson learned is to inject the video every time the page loads.
 *
 * Note:
 * We are using console logs inside the injected script because passing the logger
 * via `args` to `chrome.scripting.executeScript` did not work - methods were undefined.
 * Based on this, it appears we are not able to get the whole object reference.
 *
 * Note:
 * Using window.console.log to ensure we're calling the original console.log,
 * in case the page overrides or modifies console.log.
 */
const injectLocalVideo = (blobURL: string, targetUrl: string) => {
  window.console.log(`[Video Injection Script] Beginning execution`);

  // Handle errors and early returns
  const url = window.location.href;
  const isScriptTarget = url.includes(targetUrl);
  if (!isScriptTarget) {
    window.console.error(
      `[Video Injection Script] Script expected to run at URL ${targetUrl} but got ${url}`,
    );
    return;
  }

  const videoRegistryId = url.split('/').slice(-1)[0].split('?')[0];
  if (!videoRegistryId) {
    window.console.error(
      `[Video Injection Script] Expected a video registry ID at the end of the URL but got ${url}`,
    );
    return;
  }

  // Create the request for the local video
  const request = new XMLHttpRequest();
  request.open('GET', blobURL);
  request.responseType = 'blob';

  // Attach lifecycle methods to the request
  request.onloadstart = function () {
    window.console.log(
      '[Video Injection Script] Started loading the local video',
    );
  };

  request.onreadystatechange = function (this) {
    if (this.status >= 400) {
      window.console.error(
        `[Video Injection Script] Failed to load the local video from ${blobURL}.\n` +
          `Request: ${JSON.stringify(this)}`,
      );
      this.abort();
    }
  };

  request.onload = function (this) {
    window.console.log(
      `[Video Injection Script] Successfully loaded the local video.\n` +
        `Response: ${JSON.stringify(this.response)}`,
    );
    const objectUrl = URL.createObjectURL(this.response);
    const localStorageKey = 'videoBlob-' + videoRegistryId;
    const localStorageValue = objectUrl;
    localStorage.setItem(localStorageKey, localStorageValue);
    window.console.log(
      `[Video Injection Script] Saved the following data to local storage:\n` +
        `{ ${localStorageKey}: ${localStorageValue} }`,
    );
  };

  // Send the request and wait for the lifecycle methods to run
  request.send();
};
