import { Instance, types } from 'mobx-state-tree';

interface NewUploadingInProgress {
  recordingId: string;
  duration: number;
}

export const UploadingInProgress = types
  .model('UploadingInProgress', {
    recordingId: types.optional(types.string, ''),
    duration: types.optional(types.number, 0),
    status: types.optional(
      types.union(
        types.literal('not-started'),
        types.literal('in-progress'),
        types.literal('completed'),
        types.literal('error'),
      ),
      'not-started',
    ),
    progress: types.optional(types.number, 0),
  })
  .views((self) => {
    return {
      isUploading() {
        return !!self.recordingId && self.status !== 'completed';
      },
    };
  })
  .actions((self) => {
    return {
      setUploadingInProgress({
        recordingId,
        duration,
      }: NewUploadingInProgress) {
        self.recordingId = recordingId;
        self.duration = duration;
        self.status = 'in-progress';
        self.progress = 0;
      },
      resetUploadInProgress() {
        self.recordingId = '';
        self.duration = 0;
        self.status = 'not-started';
        self.progress = 0;
      },
      setStatus(status: 'not-started' | 'in-progress' | 'completed' | 'error') {
        self.status = status;
      },
      setProgress(progress: number) {
        self.progress = progress;
      },
    };
  });

export type IUploadingInProgress = Instance<typeof UploadingInProgress>;
