import { useRef, useEffect, useCallback } from 'react';
import { useControllerState } from '@castify/record-mv3/record-components';
import { useUploadVideoMutation } from './useUploadVideoMutation';
import { getIsControllerTabActive } from '../util/controllerTab';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { refreshFirebaseToken } from '@castify/record-mv3/common/auth';
import { UploadError } from '../util/uploadErrors';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';
import { getRecordingData } from '../../recording-recovery/utils/recordingProcessor';

type ExtensionMessage = {
  type: 'stateUpdate';
  data: {
    [key: string]: {
      drive: {
        state: 'uploading';
        progress: number;
        fileId: string;
        target: 'drive';
        isSyncUpload: boolean;
      };
    };
  };
};

interface Props {
  onUploadComplete?: () => void;
  onUploadError?: (type: string) => void;
}

export const useAutoUpload = ({
  onUploadComplete = () => {},
  onUploadError = () => {},
}: Props) => {
  const {
    uploadingInProgress,
    recordingStore,
    recorderStatus,
    recordingSettings,
    isRecording,
  } = useControllerState();
  const connectedPortsRef = useRef(new Map<string, chrome.runtime.Port>());
  const currentVersion =
    chrome.runtime.getManifest().version_name + getExtensionBrowserType();
  const logger = new ServiceWorkerLogger(
    environment.logServiceUrl,
    getFirebaseAccessToken,
    {
      appName: 'useAutoUpload',
      buildId: currentVersion,
    },
  );

  useEffect(() => {
    function onConnect(port: chrome.runtime.Port) {
      if (!port.name.includes('uploader')) return;
      const ports = connectedPortsRef.current;
      ports.set(port.name, port);

      port.onDisconnect.addListener(() => {
        ports.delete(port.name);
      });
    }
    chrome.runtime.onConnectExternal.addListener(onConnect);
    return () => {
      chrome.runtime.onConnectExternal.removeListener(onConnect);
    };
  }, []);

  const { mutateAsync: uploadVideo } = useUploadVideoMutation({
    onUploadProgress: (recordingId: string, progress: number) => {
      uploadingInProgress.setProgress(progress);
      const update: ExtensionMessage = {
        type: 'stateUpdate',
        data: {
          [recordingId]: {
            drive: {
              state: 'uploading',
              progress: progress / 100,
              fileId: recordingId,
              target: 'drive',
              isSyncUpload: true,
            },
          },
        },
      };
      const port = connectedPortsRef.current.get('uploader/' + recordingId);
      port?.postMessage(update);
    },
    onSuccess: async (_data, variables) => {
      logger.info(
        `Recording ${variables.recording.id} onSuccess triggered, removing recording`,
      );
      await recordingStore.removeRecording(variables.recording.id);
      uploadingInProgress.setStatus('completed');
      uploadingInProgress.resetUploadInProgress();
      onUploadComplete();
    },
    onError: onUploadError,
  });

  // Attempt to convert recording recovery on load
  useEffect(() => {
    recordingStore.saveRecoveryRecording();
  }, []);

  const handleCannotUpload = useCallback(async () => {
    const isControllerTabActive = await getIsControllerTabActive();
    const shouldCloseControllerTab =
      !recordingStore.recoveryRecording &&
      !uploadingInProgress.isUploading() &&
      !recordingStore.hasRecordingsToUpload() &&
      !isRecording() &&
      !recordingSettings.debugMode &&
      !isPopupOpen() &&
      !isControllerTabActive;
    if (shouldCloseControllerTab) {
      window.close();
    }
  }, [
    isRecording,
    logger,
    recordingSettings.debugMode,
    recordingStore,
    uploadingInProgress,
  ]);

  const handleCanUpload = useCallback(async () => {
    logger.info('Getting the next recording to upload');
    const recording = recordingStore.getNextRecordingToUpload();
    if (!recording) {
      logger.error('Could not find the next recording to upload');
      return;
    }

    logger.info(
      `Beginning upload process of the following recording: ` +
        JSON.stringify(recording, null, 2),
    );
    uploadingInProgress.setUploadingInProgress({
      recordingId: recording.id,
      duration: recording.metadata.duration / 1000,
    });

    let blob = null;
    try {
      const recordingData = await getRecordingData(
        recording.id,
        recording.metadata.mimeType,
      );
      blob = recordingData.blob;

      if (!blob) {
        logger.error(`Received empty blob from recording ${recording.id}`);
        throw new Error('Blob not found');
      }
      if (blob.size === 0) {
        logger.error(
          `Received blob with size 0 bytes from recording ${recording.id}`,
        );
        throw new Error('Blob size is 0 bytes');
      }
    } catch (error) {
      logger.error(
        `Could not create blob from recording ${recording.id}: ` +
          JSON.stringify(error),
      );
      await recordingStore.removeRecording(recording.id);
      uploadingInProgress.resetUploadInProgress();
      onUploadError(UploadError.GENERIC);
      return;
    }

    try {
      logger.info(`Attempting to upload recording ${recording.id}`);
      await uploadVideo({ blob, recording });
      logger.info(`Finished uploading recording ${recording.id}`);
    } catch (error) {
      logger.error(
        `Failed to upload recording ${recording.id}: ` + JSON.stringify(error),
      );
      if (error?.message?.includes('401') || error?.message?.includes('403')) {
        await refreshFirebaseToken();
      }
      onUploadError(UploadError.GENERIC);
      setTimeout(() => {
        if (uploadingInProgress.progress === 0) {
          uploadingInProgress.resetUploadInProgress();
        }
      }, 10_000);
      return;
    }

    logger.info(`Successfully uploaded recording ${recording.id}`);
  }, [logger, recordingStore, uploadVideo, uploadingInProgress]);

  // Core loop of checking if file can be uploaded or controller can be closed
  useEffect(() => {
    const interval = setInterval(() => {
      const canUpload =
        (recorderStatus === 'initialized' || recorderStatus === 'error') &&
        !uploadingInProgress.isUploading() &&
        recordingStore.hasRecordingsToUpload();
      canUpload ? handleCanUpload() : handleCannotUpload();
    }, 2000);

    return () => clearInterval(interval);
  }, [
    uploadingInProgress,
    recordingStore,
    recorderStatus,
    handleCanUpload,
    handleCannotUpload,
  ]);
};

const isPopupOpen = () =>
  chrome.extension
    .getViews()
    .some((view) => view.location.href.includes('initializer.html'));
