import { environment } from '@castify/record-mv3/environment';
import { safeWindowOpen } from '@cfy/fe-common';
import { useHttpClient } from '../hooks/useHttpClient';

export interface Seat {
  organization: { id: string };
  licenseId: string;
}

/**
 * Generates the appropriate upgrade URL by fetching user seats on demand.
 *
 * @param isUserManagementEnabled - Whether user management feature is enabled
 * @param activeOrgId - The active organization ID
 * @returns Promise that resolves to the upgrade URL
 */
export const generateUpgradeUrl = async (
  isUserManagementEnabled: boolean,
  activeOrgId?: string,
): Promise<string> => {
  const httpClient = useHttpClient();
  let upgradeUrl = `${environment.externalLinks.cartPage}?term=annual&plan=pro`;

  if (isUserManagementEnabled && activeOrgId) {
    try {
      // Fetch seats on demand
      const { data: seats } = await httpClient.get<Seat[]>(
        `${environment.licensingServiceUrl}/seats/me`,
      );

      // Find the active seat for the organization
      const activeSeat = seats.find(
        (seat: Seat) => seat.organization.id === activeOrgId,
      );

      if (activeSeat?.licenseId) {
        upgradeUrl = `${environment.externalLinks.accountPage}/update-subscription?licenseId=${activeSeat.licenseId}`;
      }
    } catch (error) {
      // Fall back to default cart URL if seats fetch fails
      // Error is logged silently, user still gets redirected
    }
  }

  return upgradeUrl;
};

/**
 * Opens the upgrade URL in a new tab/window after generating it on demand.
 *
 * @param isUserManagementEnabled - Whether user management feature is enabled
 * @param activeOrgId - The active organization ID
 * @param openFunction - Function to open the URL (default: window.open)
 */
export const openUpgradeUrl = async (
  isUserManagementEnabled: boolean,
  activeOrgId?: string,
): Promise<void> => {
  const upgradeUrl = await generateUpgradeUrl(
    isUserManagementEnabled,
    activeOrgId,
  );
  safeWindowOpen(upgradeUrl, '_blank');
};
