export const getIsControllerTabActive = async () => {
  return await chrome.tabs
    .query({
      url: `${window.location.origin}/controller.html`,
    })
    .then((tabArray) => {
      if (tabArray.length === 0) return false;
      return tabArray[0].active;
    })
    .catch(() => {
      return false;
    });
};
