import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { forwardRef, useImperativeHandle, useState } from 'react';
import { useInView } from 'react-intersection-observer';
import { useAutoScroll } from './useAutoScroll';

const FADE_SIZE = '32px';
const SCROLL_BAR_SIZE = '16px';

// Oriol way (1 row / 2 rows)
// const STEP_SIZE = 28 // 56
// const INTERVAL = 4000 // 8000
// const ANIMATION_DURATION = 300 // 600
// const INITIAL_DELAY = 12000

// Product choices:
const STEP_SIZE = 56;
const INTERVAL = 4000;
const ANIMATION_DURATION = 600;
const INITIAL_DELAY = 5000;

interface Props {
  text?: string;
  disableAutoScroll?: boolean;
  initialDelay?: number;
}

export const Teleprompter = forwardRef(
  (
    {
      text = '',
      disableAutoScroll = false,
      initialDelay = INITIAL_DELAY,
    }: Props,
    ref,
  ) => {
    const [refTop, isTopInView] = useInView({ initialInView: true });
    const [refBottom, isBottomInView] = useInView();
    const [isHovered, setIsHovered] = useState(false);
    const { autoScrollRef, resetScroll } = useAutoScroll({
      disableAutoScroll: isHovered || disableAutoScroll,
      stepSize: STEP_SIZE,
      interval: INTERVAL,
      animationDuration: ANIMATION_DURATION,
      initialDelay,
    });

    useImperativeHandle(
      ref,
      () => ({
        resetScroll,
      }),
      [],
    );

    return (
      <Box
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        sx={{
          position: 'fixed',
          width: 420,
          height: 280,
          top: '32px',
          left: '50%',
          transform: 'translateX(-50%)',
          background: 'rgba(0, 0, 0, 0.40)',
          color: 'white',
          borderRadius: '8px',
          padding: '16px',
          boxShadow: 3,
          boxSizing: 'border-box',
          overflow: 'hidden',
          border: '1px solid rgba(0, 0, 0, 0.12)',
        }}
      >
        <Box
          sx={{
            width: '100%',
            height: '100%',
            border: '1px solid rgba(0, 0, 0, 0.12)',
            borderRadius: '4px',
            overflow: 'hidden',
            boxSizing: 'border-box',
          }}
        >
          <Box
            ref={autoScrollRef}
            sx={{
              width: '100%',
              height: '100%',
              padding: '0 16px',
              boxSizing: 'border-box',
              overflowY: 'auto',
              maskImage: `linear-gradient(
                to bottom,
                rgba(0,0,0,${!isTopInView ? '0' : '1'}) 0px,
                rgba(0,0,0,1) ${FADE_SIZE},
                rgba(0,0,0,1) calc(100% - ${FADE_SIZE}),
                rgba(0,0,0,${!isBottomInView ? '0' : '1'}) 100%)
              ,linear-gradient(
                to right,
                rgba(0,0,0,0) 0%,
                rgba(0,0,0,0) calc(100% - ${SCROLL_BAR_SIZE}),
                rgba(0,0,0,1) calc(100% - ${SCROLL_BAR_SIZE}),
                rgba(0,0,0,1) 100%
              )`,
              WebkitMaskImage: `linear-gradient(
                to bottom,
                rgba(0,0,0,${!isTopInView ? '0' : '1'}) 0px,
                rgba(0,0,0,1) ${FADE_SIZE},
                rgba(0,0,0,1) calc(100% - ${FADE_SIZE}),
                rgba(0,0,0,${!isBottomInView ? '0' : '1'}) 100%)
              ,linear-gradient(
                to right,
                rgba(0,0,0,0) 0%,
                rgba(0,0,0,0) calc(100% - ${SCROLL_BAR_SIZE}),
                rgba(0,0,0,1) calc(100% - ${SCROLL_BAR_SIZE}),
                rgba(0,0,0,1) 100%
              )`,
            }}
          >
            <div style={{ height: 0, marginBottom: '8px' }} ref={refTop} />
            <Typography
              variant="body1"
              sx={{
                fontFamily: 'Fellix, sans-serif',
                fontWeight: 600,
                fontSize: '20px',
                lineHeight: '140%',
                letterSpacing: '0px',
                verticalAlign: 'middle',
                whiteSpace: 'pre-wrap',
              }}
            >
              {text}
            </Typography>
            <div style={{ height: 0, marginTop: '8px' }} ref={refBottom} />
          </Box>
        </Box>
      </Box>
    );
  },
);
