import { environment } from '@castify/record-mv3/environment';
import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';
import ReplayRoundedIcon from '@mui/icons-material/ReplayRounded';
import OpenInNewRoundedIcon from '@mui/icons-material/OpenInNewRounded';
import styles from './DialogStyles.styles';
import { focusControllerTab } from '@castify/record-mv3/common';
import { useEffect } from 'react';

const logger: IBrowserLogger = createBrowserLogger('GoogleDriveScopsDialog');

interface DialogProps {
  isOpen: boolean;
  onTryAgain: () => void;
}

export const GoogleDriveScopsDialog = ({ isOpen, onTryAgain }: DialogProps) => {
  useEffect(() => {
    if (isOpen) focusControllerTab();
  }, [isOpen]);

  const handleGrandsClick = () => {
    logger.info('Google Drive scopes: forcing consent for login clicked');
    chrome.tabs.create({ url: environment.externalLinks.forceConsentSignIn });
  };
  const handleTryAgainClick = () => {
    logger.info("Google Drive scopes: 'Try Again' button clicked");
    onTryAgain();
  };
  return (
    <Dialog open={isOpen} maxWidth="xs">
      <DialogTitle css={styles.title}>
        Google Drive access not granted
      </DialogTitle>
      <DialogContent>
        <DialogContentText css={styles.contentText}>
          We don't seem to have permissions to upload your video to Google
          Drive. Please grant access to upload the video to your storage.
        </DialogContentText>
      </DialogContent>
      <DialogActions css={styles.actions}>
        <Button
          variant="outlined"
          color="info"
          startIcon={<ReplayRoundedIcon />}
          onClick={handleTryAgainClick}
        >
          Try Again
        </Button>
        <Button
          variant="contained"
          color="primary"
          startIcon={<OpenInNewRoundedIcon />}
          onClick={handleGrandsClick}
        >
          Allow Permissions
        </Button>
      </DialogActions>
    </Dialog>
  );
};
