import MenuItem from '@mui/material/MenuItem';
import Select from '@mui/material/Select';
import Typography from '@mui/material/Typography';
import {
  AUTO_STOP_PRESETS,
  AUTO_STOP_OFF_VALUE,
  AUTO_STOP_FREE_TIER_MAX_VALUE,
} from '@castify/record-mv3/common';

interface Props {
  autoStopTime: number;
  setAutoStopTime: (value: number) => void;
  isFreeUser: boolean;
}

export function AutoStopSelect({
  autoStopTime,
  setAutoStopTime,
  isFreeUser,
}: Props) {
  return (
    <Select
      fullWidth
      size="small"
      value={autoStopTime}
      onChange={(event) => {
        setAutoStopTime(Number(event.target.value));
      }}
    >
      <MenuItem key="OFF" value={AUTO_STOP_OFF_VALUE} disabled={isFreeUser}>
        <Typography>OFF</Typography>
      </MenuItem>
      {Object.entries(AUTO_STOP_PRESETS).map(([key, value]) => (
        <MenuItem
          key={key}
          value={value}
          disabled={isFreeUser && value > AUTO_STOP_FREE_TIER_MAX_VALUE}
        >
          {value} minutes
        </MenuItem>
      ))}
    </Select>
  );
}
