import { useHttpClient } from '@castify/record-mv3/common';
import { useMutation } from '@tanstack/react-query';
import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import axios from 'axios';
interface UploadVideoChunkParam {
  uri: string;
  recordingId: string;
  video: Blob;
  currentByte: number;
  onUploadProgress: (recordingId: string, progress: number) => void;
}

export interface UploadVideoChunkResponse {
  status: number;
  nextByte: number;
  message?: string;
}

// chunk size should be a multiple of 256 KiB
const MAX_CHUNK_SIZE = 256 * 1024 * 1000; // 262mb
// const MAX_RETRY_DELAY = 60000 as const;

export function useUploadVideoChunkMutation() {
  const logger: IBrowserLogger = createBrowserLogger(
    'UploadVideoChunkMutation',
  );

  const httpClient = useHttpClient();
  return useMutation<UploadVideoChunkResponse, Error, UploadVideoChunkParam>(
    async ({
      uri,
      recordingId,
      video,
      currentByte,
      onUploadProgress,
    }: UploadVideoChunkParam): Promise<UploadVideoChunkResponse> => {
      const chunkSize = Math.min(video.size, MAX_CHUNK_SIZE);
      const endByteIdx = Math.min(currentByte + chunkSize, video.size) - 1;
      const contentRange = `bytes ${currentByte}-${endByteIdx}/${video.size}`;
      const chunk = video.slice(currentByte, endByteIdx + 1);
      const response = await httpClient.put<UploadVideoChunkResponse>(
        uri,
        chunk,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
            'Content-Range': contentRange,
          },
          onUploadProgress: ({ loaded }: { loaded: number }) => {
            const progress = Math.floor(
              ((currentByte + loaded) * 100) / video.size,
            );
            onUploadProgress(recordingId, progress);
          },
          // 409 Conflict status usually meant the video was already uploaded and tehre is an error.  Here we choose to pass it off as a success
          validateStatus: (status) =>
            (status >= 200 && status < 400) || status === 409,
        },
      );

      const range = response.headers.range ?? '';
      const rgx = range.match(/bytes=0-(\d+)/) ?? [];
      const nextByte = rgx.length > 0 ? Number(rgx[1]) + 1 : 0;
      return {
        status: response.status,
        nextByte,
      };
    },
    {
      onError: (error, { recordingId, onUploadProgress }) => {
        onUploadProgress(recordingId, 0);
        if (axios.isAxiosError(error)) {
          // Log the error response
          logger.error(
            `Error during video chunk upload: message: ${
              error.message
            }, response: ${JSON.stringify(error.response?.data)}`,
          );
        } else {
          logger.error(
            `Error during video chunk upload: message: ${error.message}`,
          );
        }
      },
    },
  );
}
