import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';
import { colors } from '@cfy/fe-common';

interface Props {
  isOpen?: boolean;
  onClose?: () => void;
  onConfirm?: () => void;
}

export const CloseTeleprompterDialog = ({
  isOpen = false,
  onClose = () => {},
  onConfirm = () => {},
}: Props) => {
  return (
    <Dialog open={isOpen} onClose={onClose}>
      <DialogTitle
        sx={{
          minWidth: '445px',
          fontSize: '1.5rem',
          fontWeight: 700,
          paddingBottom: '7px',
          color: colors.textPrimary,
        }}
      >
        Cancel recording?
      </DialogTitle>
      <DialogContent>
        <DialogContentText
          sx={{
            fontSize: '1rem',
            fontWeight: 300,
            lineHeight: '16px',
            color: colors.textPrimary,
          }}
        >
          Your changes may not be saved.
        </DialogContentText>
      </DialogContent>
      <DialogActions
        sx={{
          paddingBottom: '24px',
          paddingRight: '21px',
        }}
      >
        <Button color="info" variant="outlined" onClick={onClose}>
          Never Mind
        </Button>
        <Button variant="contained" color="primary" onClick={onConfirm}>
          Yes, Cancel
        </Button>
      </DialogActions>
    </Dialog>
  );
};
