import { useMutation } from '@tanstack/react-query';
import {
  IRecordingStoreRecord,
  useControllerState,
} from '@castify/record-mv3/record-components';
import { useStartVideoPostMutation } from './useStartVideoPostMutation';
import { useUpdateDraftVideoMutation } from './useUpdateDraftVideoMutation';
import {
  useUploadVideoChunkMutation,
  UploadVideoChunkResponse,
} from './useUploadVideoChunkMutation';
import { StorageType, useContentDriveRoot } from '@castify/record-mv3/common';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import axios from 'axios';
import { useGenerateVideoId } from './useGenerateVideoId';
import { refreshFirebaseToken } from '@castify/record-mv3/common/auth';
import { UploadError } from '../util/uploadErrors';
import { useGenerateGoogleDriveIdMutation } from './useGenerateGoogleDriveIdMutation';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';
export interface UploadVideoProps {
  onUploadProgress: (recordId: string, progress: number) => void;
  onSuccess: (data: unknown, variables: UploadVideoParams) => void;
  onError: (type: string) => void;
}

export interface UploadVideoParams {
  blob: Blob;
  recording: IRecordingStoreRecord;
}

export function useUploadVideoMutation({
  onUploadProgress,
  onSuccess,
  onError,
}: UploadVideoProps) {
  const currentVersion =
    chrome.runtime.getManifest().version_name + getExtensionBrowserType();
  const logger = new ServiceWorkerLogger(
    environment.logServiceUrl,
    getFirebaseAccessToken,
    {
      appName: 'UploadVideoMutation',
      buildId: currentVersion,
    },
  );

  const { uploadingInProgress, recordingSettings } = useControllerState();

  const { mutateAsync: startVideoPost } = useStartVideoPostMutation();
  const { mutateAsync: generateVideoIdAndCreateDraft } = useGenerateVideoId();
  const { mutateAsync: uploadVideoChunk } = useUploadVideoChunkMutation();
  const { mutateAsync: updateDraftVideo } = useUpdateDraftVideoMutation();
  const { mutateAsync: fetchDriveRootId } = useContentDriveRoot();
  const { mutateAsync: generateGoogleDriveId } =
    useGenerateGoogleDriveIdMutation();

  return useMutation<boolean, Error, UploadVideoParams>(
    async ({ blob, recording }: UploadVideoParams) => {
      let source = recording.metadata.source as StorageType;

      const generateUri = async () => {
        // Get video Registry Id
        let { videoRegistryId } = recording.metadata;
        let driveFileId = recording.metadata.driveFileId;
        let driveRootId = '';

        try {
          driveRootId = await fetchDriveRootId();
        } catch (error) {
          logger.error('Failed to fetch drive root id: ' + error);
        }

        if (!videoRegistryId) {
          const {
            driveFileId: newDriveFileId,
            videoId,
            metadata,
            source: draftSource,
          } = await generateVideoIdAndCreateDraft({
            id: recording.id,
            approximateDuration: recording.metadata.duration,
            title: recording.metadata.title,
            type: recordingSettings.recordingType,
            orgId: recording.orgId,
          });
          videoRegistryId = videoId;
          source = draftSource;
          recording.updateMetadata({ videoRegistryId, metadata, driveFileId });
          driveFileId = newDriveFileId;
        } else if (!driveFileId && source === StorageType.DRIVE) {
          driveFileId = await generateGoogleDriveId();
          recording.updateMetadata({ driveFileId });
        }

        logger.info('videoRegistry id used ' + videoRegistryId);

        // Get Google Drive Screencastify folder, defaults to root folder
        const getUri = (driveRootId?: string) =>
          startVideoPost({
            video: blob,
            metadata: {
              ...recording.metadata.metadata,
              ...(source === 'drive' &&
                // google drive v3 expects an array of folder Ids
                //   driveRootId && { parents: [driveRootId] }),
                // google drive v2 expected an array of ParentReference with at least the id
                // of the folder
                driveRootId && { parents: [{ id: driveRootId }] }),
            },
            videoRegistryId,
            source,
          });

        const uri = await getUri(driveRootId).catch(async (e) => {
          if (e.response.status === 404) {
            driveRootId = await fetchDriveRootId({ ignoreCache: true });
          }
          const newURI = await getUri(driveRootId);
          return newURI;
        });
        if (!uri) throw new Error('Failed to get upload URI');
        return { uri, videoRegistryId, driveFileId };
      };

      const uploadChunks = async (fileId: string, uri: string) => {
        let response = { status: 308, nextByte: 0 } as UploadVideoChunkResponse;
        while (response.status === 308) {
          logger.info(`uploading chunks from ${fileId} to ${uri}`);
          response = await uploadVideoChunk({
            uri,
            recordingId: recording.id,
            video: blob,
            currentByte: response.nextByte,
            onUploadProgress,
          });
          logger.info(
            `video put chunk success status: ${response.status} next byte: ${response.nextByte}`,
          );
        }
        return response.status;
      };

      const upload = async () => {
        const { uri, videoRegistryId, driveFileId } = await generateUri();
        logger.info(`uploading ${videoRegistryId} to ${uri}...`);
        const status = await uploadChunks(driveFileId, uri);

        if (status === 200 || status === 409) {
          const success = await updateDraftVideo({
            videoRegistryId,
            driveFileId,
            draft: false,
          });
          if (!success) throw new Error('Failed to update draft video');
          return true;
        } else {
          logger.error('Unexpected response status: ' + status);
          throw new Error(`Unexpected response status: ${status}`);
        }
      };

      try {
        return await upload();
      } catch (error) {
        if (axios.isAxiosError(error)) {
          const status = error.response?.status;
          const message = error.response?.data?.message;
          if (
            status === 400 &&
            message === 'The provided file ID is not usable'
          ) {
            // Handle 400 error
            logger.error(
              `Received 400 on upload ${JSON.stringify(
                error.response,
              )}, attempting new drive id`,
            );
            recording.updateMetadata({ driveFileId: '' });
          } else if (status === 401) {
            // Handle 401 error for token refresh
            logger.error(
              `Received 401 on upload ${JSON.stringify(
                error.response,
              )}, attempting refresh`,
            );
            await refreshFirebaseToken();
            recording.updateMetadata({ driveFileId: '' });
          } else if (status === 403) {
            // Handle 403 forbidden error
            logger.error(
              `Received 403 forbidden on upload ${JSON.stringify(
                error.response,
              )}, attempting refresh`,
            );
            if (
              message?.includes(
                'Request had insufficient authentication scopes.',
              )
            ) {
              logger.error('Google scopes error');
              onError(UploadError.GOOGLE_SCOPES);
              recording.updateMetadata({ driveFileId: '' });
              throw error;
            }
            if (
              message?.includes(
                'The user has exceeded their Drive storage quota',
              )
            ) {
              logger.error('Google drive is full');
              onError(UploadError.GOOGLE_FULL_STORAGE);
              throw error;
            }
            recording.updateMetadata({ driveFileId: '' });
          } else if (status === 404) {
            // Handle 404 error for file not found
            logger.error(
              `Received 404 on upload ${JSON.stringify(
                error.response,
              )}, attempting refresh`,
            );
            if (message?.includes('File not found')) {
              logger.error('Google drive file not found:', message);
              await chrome.storage.local.remove('DRIVE_FOLDER_ID');
            }
            recording.updateMetadata({ driveFileId: '' });
          } else if (status !== undefined && [502, 503, 504].includes(status)) {
            // Handle network-related errors (502, 503, 504)
            logger.error(
              `Received network error ${status} on upload ${JSON.stringify(
                error.response,
              )}`,
            );
            uploadingInProgress.setProgress(0);
            throw error; // Re-throw to trigger retry or handle further up
          } else {
            // Handle other Axios errors
            logger.error('Unexpected Axios error on upload: ' + error);
            uploadingInProgress.setProgress(0);
            throw error;
          }
        } else {
          // Handle non-Axios errors
          logger.error('Unexpected error on upload: ', error);
          uploadingInProgress.setProgress(0);
          throw error;
        }
        return await upload();
      }
    },
    {
      onSuccess,
      onError: (error) => {
        logger.error(`onError - error on upload`, { error });
        uploadingInProgress.setProgress(0);
        throw error;
      },
    },
  );
}
