import { useMemo } from 'react';
import { useFirebase } from './useFirebase';
import { getRemoteConfig } from 'firebase/remote-config';

/**
 * Helper for accessing the Firebase Remote Config.
 *
 * Note: Remote Config has a dependency on IndexedDB so a mock will be needed to
 * test files that use Remote Config.
 */
export const useRemoteConfig = () => {
  const { firebaseApp } = useFirebase();

  return useMemo(() => {
    const remoteConfig = getRemoteConfig(firebaseApp);

    // These are based on the Remote Config settings from the legacy app:
    // https://github.com/screencastify/castify/blob/main/lib/client-common/src/lib/remote-config.service.ts#L218
    remoteConfig.settings = {
      minimumFetchIntervalMillis: 3600000,
      // use 0 fetch interval during development
      // minimumFetchIntervalMillis: 0,
      fetchTimeoutMillis: 600000,
    };

    return remoteConfig;
  }, [firebaseApp]);
};
