import { setExtensionIcon } from '@castify/record-mv3/chrome-actions';
import {
  DiscardVideoScriptConfirmDialog,
  ControllerProtocolDefinition,
  ControllerStorageDriver,
  DeleteRecordingConfirmDialog,
  findOrCreateControllerTab,
  IRecording,
  RecordingManager,
  RestartRecordingConfirmDialog,
  useControllerState,
  WebcamPageControls,
} from '@castify/record-mv3/record-components';
import { createBrowserLogger } from '@cfy/fe-monitoring';
import Paper from '@mui/material/Paper';
import Typography from '@mui/material/Typography';
import { observer } from 'mobx-react-lite';
import { useEffect, useRef, useState } from 'react';
import { FreeTierRecordingAlert } from '../free-tier/FreeTierRecordingAlert';
import Webcam from '../webcam/Webcam';
import styles from './WebcamPage.styles';
import { TeleprompterModal } from './TeleprompterModal';
import { useTeleprompterStore } from '@castify/record-mv3/common/stores';
import { Teleprompter } from './Teleprompter';
import Box from '@mui/material/Box';
import { CountdownOverlay } from '../extension-overlay/CountdownOverlay';

type Message = Pick<
  ControllerProtocolDefinition['RECORDING_CONTROLLER_START'],
  'payload'
>;

interface IWebCamPageProps {
  recording: IRecording;
  recordingManager: RecordingManager;
  onStart: (message: Message) => void;
}
const WebcamPage = observer(
  ({ recording, recordingManager, onStart }: IWebCamPageProps) => {
    const logger = createBrowserLogger('WebcamPage');
    const { userState, recordingSettings } = useControllerState();
    const useTeleprompter = useTeleprompterStore((s) => s.useTeleprompter);
    const scriptContent = useTeleprompterStore((s) => s.scriptContent);
    const setUseTeleprompter = useTeleprompterStore(
      (s) => s.setUseTeleprompter,
    );
    const showTeleprompterModal = useTeleprompterStore(
      (s) => s.showTeleprompterModal,
    );
    const showTeleprompter = useTeleprompterStore((s) => s.showTeleprompter);
    const setShowTeleprompterModal = useTeleprompterStore(
      (s) => s.setShowTeleprompterModal,
    );
    const setShowTeleprompter = useTeleprompterStore(
      (s) => s.setShowTeleprompter,
    );
    const resetTeleprompterStore = useTeleprompterStore(
      (s) => s.resetTeleprompterStore,
    );
    const [recordingState, setRecordingState] = useState('');

    const teleprompterRef = useRef<{ resetScroll: () => void } | null>(null);

    useEffect(() => {
      getRecordingState();
    });
    const getRecordingState = () => {
      if (recording.state === 'recording') {
        setRecordingState('Rec');
      } else if (recording.state === 'paused') {
        setRecordingState('Paused');
      }
    };

    const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
    const [isRestartDialogOpen, setIsRestartDialogOpen] = useState(false);
    const [isDiscardScriptDialogOpen, setIsDiscardScriptDialogOpen] =
      useState(false);

    const startWebcamRecording = async () => {
      try {
        await ControllerStorageDriver.setRecorderStatus('acquiring-media');
        const controllerTab = await findOrCreateControllerTab();
        if (!controllerTab?.id) return;
        onStart({
          payload: {
            isCurrentTabInjectable: false,
            activeTabId: controllerTab.id,
          },
        });
      } catch (error) {
        logger.error('Recording error:', error);
      }
    };

    const handleStartRecording = async () => {
      setShowTeleprompterModal(false);
      setShowTeleprompter(true);
      startWebcamRecording();
    };

    const handleDiscardScript = async () => {
      resetTeleprompterStore();
      setIsDiscardScriptDialogOpen(false);
      setUseTeleprompter(false);
      startWebcamRecording();
    };

    const toggleShowTeleprompter = () => {
      setShowTeleprompter(!showTeleprompter);
    };

    return (
      <div css={styles.videoContainer}>
        {recordingSettings.useCountIn && <CountdownOverlay />}
        <div css={[styles.videoWrapper, styles.videoWrapperBorder]}>
          {(recording.state === 'recording' ||
            recording.state === 'paused' ||
            recording.state === 'counting-in') && (
            <Paper
              css={[
                styles.statusIndicatorContainer,
                recording.state === 'recording'
                  ? styles.recordingStatusIndicator
                  : styles.pauseStatusIndicator,
              ]}
            >
              <Typography css={styles.statusIndicatorText}>
                {recordingState}
              </Typography>
            </Paper>
          )}
          {/* variant doesn't do anything here only applies when circular is true */}
          <Webcam variant={'lg'} />
        </div>

        {userState.hasUserData && userState.isFreeUser && (
          <FreeTierRecordingAlert
            recordingManager={recordingManager}
            recording={recording}
          />
        )}

        <WebcamPageControls
          recordingManager={recordingManager}
          recording={recording}
          onDelete={() => setIsDeleteDialogOpen(true)}
          onRestart={() => setIsRestartDialogOpen(true)}
          useTeleprompter={useTeleprompter}
          showTeleprompter={showTeleprompter}
          onShowTeleprompterChange={toggleShowTeleprompter}
        />

        {useTeleprompter && !showTeleprompterModal && (
          <Box
            sx={{
              opacity: showTeleprompter ? 1 : 0,
              pointerEvents: showTeleprompter ? 'initial' : 'none',
            }}
          >
            <Teleprompter
              ref={teleprompterRef}
              text={scriptContent}
              disableAutoScroll={recording.state !== 'recording'}
            />
          </Box>
        )}

        <TeleprompterModal
          open={showTeleprompterModal}
          onStartRecording={handleStartRecording}
          onCancelScript={() => setIsDiscardScriptDialogOpen(true)}
        />

        <DiscardVideoScriptConfirmDialog
          isOpen={isDiscardScriptDialogOpen}
          onClose={() => setIsDiscardScriptDialogOpen(false)}
          onClick={handleDiscardScript}
        />

        <DeleteRecordingConfirmDialog
          isOpen={isDeleteDialogOpen}
          onClose={() => setIsDeleteDialogOpen(false)}
          onClick={() => {
            recordingManager.deleteRecording(recording);
            setExtensionIcon(recording.state);
            setIsDeleteDialogOpen(false);
          }}
        />

        <RestartRecordingConfirmDialog
          isOpen={isRestartDialogOpen}
          onClose={() => setIsRestartDialogOpen(false)}
          onClick={() => {
            teleprompterRef.current?.resetScroll();
            recordingManager.restartRecording(
              recording,
              recordingSettings.useCountIn,
            );
            setExtensionIcon(recording.state);
            setIsRestartDialogOpen(false);
          }}
        />
      </div>
    );
  },
);
export default WebcamPage;
