import { createSyncStore } from './createSyncStore';
import { STORE_OPTIONS } from './utils';

type AdditionalData = Record<string, string | number>;

export type PendoMsg = {
  eventName?: string | null;
  additionalData?: AdditionalData;
};

interface PendoStore {
  eventList: PendoMsg[];
  queueEvent: (event: PendoMsg) => void;
  resetEventList: () => void;
}

const INIT_STATE: Pick<PendoStore, 'eventList'> = {
  eventList: [],
};

export const usePendoStore = createSyncStore<PendoStore>(
  'usePendoStore',
  {
    ...INIT_STATE,

    queueEvent: (event) => {
      const { set, eventList } = usePendoStore.getState();
      set({ eventList: [...eventList, event] });
    },
    resetEventList: () => {
      const { set } = usePendoStore.getState();
      set({ eventList: [] });
    },
  },
  STORE_OPTIONS,
);
