import { blobToFile } from './blobUtils';
import { createVideoNameWithTimestamp } from './videoNaming';
import fixWebmDuration from 'webm-duration-fix';

export const downloadVideo = async (blob: Blob) => {
  const videoTitle = createVideoNameWithTimestamp();
  const fixedBlob = await fixWebmDuration(blob).catch(() => blob);
  const creationTime = Date.now();

  const videoFile = blobToFile({
    blob: fixedBlob,
    name: videoTitle,
    type: 'video/webm',
    lastModified: creationTime,
  });

  downloadFile(videoFile, videoTitle);
};

const downloadFile = (file: MediaSource | File, name: string) => {
  const link = document.createElement('a');
  link.style.display = 'none';
  link.href = URL.createObjectURL(file);
  link.download = name;

  document.body.appendChild(link);
  link.click();

  // To make this work on Firefox we need to wait a little while before removing it.
  setTimeout(() => {
    URL.revokeObjectURL(link.href);
    link?.parentNode?.removeChild(link);
  }, 0);
};
