import { useMutation } from '@tanstack/react-query';
import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import {
  usePersonalSettingsQueryValueByKey,
  UserPersonalSettingKeys,
  StorageType,
  RecordingType,
} from '@castify/record-mv3/common';
import { createGoogleDriveMetadata } from './createGoogleDriveMetadata';
import { useCreateDraftVideoMutation } from './useCreateDraftVideoMutation';
import { useGenerateGoogleDriveIdMutation } from './useGenerateGoogleDriveIdMutation';
import { createVideoNameWithTimestamp } from '../util/videoNaming';
import { getDraftRecordingType } from '../util/getDraftRecordingType';

export interface IRecordParams {
  id: string;
  approximateDuration: number;
  title?: string;
  type: RecordingType;
  orgId?: string;
}

export const useGenerateVideoId = () => {
  const logger: IBrowserLogger = createBrowserLogger('useGeneratedVideoId');
  const {
    data: persistentStorage = StorageType.DRIVE,
    refetch: refetchPersistentStorage,
  } = usePersonalSettingsQueryValueByKey(
    UserPersonalSettingKeys.PersistentStorage,
  );
  const { mutateAsync: createDraftVideo } = useCreateDraftVideoMutation();
  const { mutateAsync: generateGoogleDriveId } =
    useGenerateGoogleDriveIdMutation();

  async function getVideoId(recordingId: string) {
    /** refeching since  */
    const { isError: persistentStorageFetchError } =
      await refetchPersistentStorage();

    if (persistentStorageFetchError) {
      logger.error(`Error while refetching persistenStorage value`);

      throw new Error('Persistent Storage unavailable');
    }

    if (persistentStorage === StorageType.DRIVE) {
      return await generateGoogleDriveId();
    }
    return recordingId;
  }

  return useMutation({
    mutationFn: async function (recording: IRecordParams) {
      const driveFileId = await getVideoId(recording.id);
      if (!driveFileId)
        throw Error(
          `Received unexpected data from call to create draft video for recording ${recording.id}.`,
        );

      const videoTitle = recording.title ?? createVideoNameWithTimestamp();

      const creationTime = Date.now();
      const draftVideoData = {
        source: persistentStorage as StorageType,
        driveFileId,
        extensionVmpId: recording.id,
        duration: recording.approximateDuration / 1000,
        creationTime,
        title: videoTitle,
        recordingType: getDraftRecordingType(recording.type),
        organizationId: recording.orgId,
      };

      const metadata = createGoogleDriveMetadata({
        videoTitle,
        driveFileId,
        duration: recording.approximateDuration,
      });

      logger.info(
        `Creating draft ${recording.id} using the following data:
          ${JSON.stringify(draftVideoData, null, 2)}
          and ${JSON.stringify(metadata, null, 2)}
        `,
      );

      const { id: videoId } = await createDraftVideo(draftVideoData);

      return {
        videoId,
        driveFileId,
        creationTime,
        metadata,
        source: persistentStorage as StorageType,
      };
    },
  });
};
