import { useEffect, useState } from 'react';
import { observer } from 'mobx-react-lite';
import {
  getRecordingManager,
  Recording,
  IRecording,
  ControllerProtocolDefinition,
  findActiveTab,
  ControllerStorageDriver,
  useSyncedControllerState,
} from '@castify/record-mv3/record-components';
import styles from './Controller.styles';
import { createProtocolHandler } from '@castify/record-mv3/chrome-messaging';

import WebcamPage from '../webcam-page/WebcamPage';
import { IBrowserLogger, createBrowserLogger } from '@cfy/fe-monitoring';
import { useRecordingStorageSyncronizer } from './hooks/useRecordingStorageSyncronizer';
import { ErrorPage, ErrorTypeEnum } from '@castify/record-mv3/error-handling';
import { createVideoNameWithTimestamp } from './util/videoNaming';
import { deleteRecordingDataById } from '@castify/record-mv3/recording-indexed-db';
import {
  USER_VIDEO_COUNT_QUERY_KEY,
  isVideoCountResponse,
} from '@castify/record-mv3/common';
import { useQueryClient } from '@tanstack/react-query';
import { openPopup } from './util/openPopup';
import { sendPendoEvent } from '../pendo/sendPendoEvent';

const logger: IBrowserLogger = createBrowserLogger('WebcamController');

interface WebcamControllerProps {
  createOnComplete: (recording: IRecording) => () => void;
  onNewDataAvailable: (
    duration: number,
    mimeType: string,
    title: string,
    orgId?: string,
  ) => void;
  onDelete: () => void;
}

export const WebcamController = observer((props: WebcamControllerProps) => {
  const { createOnComplete, onNewDataAvailable, onDelete } = props;

  const controllerState = useSyncedControllerState();
  const {
    isInCountdown,
    isRecording,
    recorderStatus,
    userState,
    recordingStore,
    recordingSettings,
  } = controllerState;

  const [recording, setRecording] = useState<IRecording>(() =>
    Recording.create({ timeLimit: recordingSettings.autoStopTime }),
  );

  const recordingManager = getRecordingManager(recordingSettings, recording.id);
  useRecordingStorageSyncronizer(recording);

  const queryClient = useQueryClient();

  const onDeleted = async () => {
    await deleteRecordingDataById(recording.id);
    onDelete();
  };

  const handleControllerStart = async (
    message: Pick<
      ControllerProtocolDefinition['RECORDING_CONTROLLER_START'],
      'payload'
    >,
  ) => {
    const recording = Recording.create({
      timeLimit: recordingSettings.autoStopTime,
      isQuickStart: message.payload.isQuickStart,
      title: createVideoNameWithTimestamp('Webcam'),
      orgId: userState.activeOrgId,
    });
    setRecording(recording);

    const currentTab = await chrome.tabs.getCurrent();
    const tabIds = {
      activeTabId: message.payload.activeTabId,
      controllerTabId: currentTab?.id as number,
    };

    const onStartRecording = async () => {
      try {
        await recordingManager.startRecording({
          recording,
          tabIds,
          onComplete: createOnComplete(recording),
          onDeleted,
          onNewDataAvailable,
          shouldCountIn: recordingSettings.useCountIn,
        });
      } catch (error) {
        logger.error(`Error on Webcam Recording Start ${error?.message}`);
        ControllerStorageDriver.setRecorderStatus('error');
      }
    };
    await onStartRecording();
  };

  useEffect(() => {
    const protocolHandler = createProtocolHandler<ControllerProtocolDefinition>(
      {
        RECORDING_CONTROLLER_START: handleControllerStart,
        RECORDING_CONTROLLER_IMMEDIATE_START: async () => {
          recordingManager.immediateStart(recording);
        },
        RECORDING_CONTROLLER_STOP: () => {
          recordingManager.stopRecording(recording);
        },
        RECORDING_CONTROLLER_PAUSE: () => {
          recordingManager.pauseRecording(recording);
        },
        RECORDING_CONTROLLER_RESUME: () => {
          recordingManager.resumeRecording(recording);
        },
        RECORDING_CONTROLLER_CLOSE: () => {
          window.close();
        },
        RECORDING_CONTROLLER_DELETE: () => {
          recordingManager.deleteRecording(recording);
          setRecording(
            Recording.create({ timeLimit: recordingSettings.autoStopTime }),
          );
        },
        RECORDING_CONTROLLER_RESTART: async () => {
          recordingManager.restartRecording(recording, true);
        },
        RECORDING_CONTROLLER_ERROR: (message) => {
          logger.error(
            'recording_controller_error - ' + message.payload.context,
          );
        },
        TOGGLE_START_STOP: async () => {
          if (isInCountdown()) return;
          if (userState.isFreeUser && userState.hasUserData) {
            const data = await queryClient
              .fetchQuery([USER_VIDEO_COUNT_QUERY_KEY])
              .catch(() => {
                logger.error('Video count error');
                return null;
              });
            if (!isVideoCountResponse(data)) {
              logger.error(
                'Video count data received does not match expected format. Skipping',
              );
              openPopup();
              return;
            }
            if (
              recordingStore.getRecordingList().length + data.videoCount >=
              userState.videoLimit
            )
              openPopup();
            return;
          }

          if (!isRecording()) {
            const activeTab = await findActiveTab();
            if (!activeTab) return;
            const isCurrentTabInjectable =
              activeTab &&
              activeTab.url &&
              (activeTab.url.startsWith('https://') ||
                activeTab.url.startsWith('http://')) &&
              !activeTab.url.startsWith('https://chrome.google.com/webstore/');
            handleControllerStart({
              payload: {
                isCurrentTabInjectable: !!isCurrentTabInjectable,
                activeTabId: activeTab.id ?? 0,
                isQuickStart: true,
              },
            });

            sendPendoEvent({
              eventName: 'MV3-clk-quick-record',
              additionalData: {},
            });
          } else {
            recordingManager.stopRecording(recording);
          }
        },
        TOGGLE_RESUME_PAUSE: async () => {
          if (recorderStatus === 'paused') {
            recordingManager.resumeRecording(recording);
          } else if (recorderStatus === 'recording') {
            recordingManager.pauseRecording(recording);
          }
        },
      },
    );

    chrome.runtime.onMessage.addListener(protocolHandler);
    chrome.runtime.sendMessage({ command: 'CONTROLLER_READY' });
    return () => chrome.runtime.onMessage.removeListener(protocolHandler);
  }, [
    createOnComplete,
    onNewDataAvailable,
    recording,
    recordingManager,
    recordingSettings,
    handleControllerStart,
  ]);

  if (!navigator.onLine && !recording.isRecordingInProgress) {
    return <ErrorPage errorType={ErrorTypeEnum.connectionError} />;
  }

  return (
    <div css={styles.controllerContainer}>
      <WebcamPage
        recording={recording}
        recordingManager={recordingManager}
        onStart={handleControllerStart}
      />
    </div>
  );
});
