import { logger } from '../authLogger';
import {
  exchangeGoogleAccessToken,
  exchangeScreencasitfyToken,
} from '../exchangeTokens';
import { refreshFirebaseToken } from '../refreshFirebaseToken';
import { useAuthStore } from '../../../stores';
import {
  shouldRefreshGoogleAccessToken,
  shouldRefreshJwt,
} from './shouldRefreshGoogleAccessToken';

const SECURITY_MARGIN = 5; // 5min

export const getFreshScreencastifyToken = async () => {
  if (!useAuthStore.getState().firebaseAccessToken) {
    logger.error('No firebase token found, refreshing firebase token');
    await refreshFirebaseToken();
  }
  const { screencastifyToken, firebaseAccessToken } = useAuthStore.getState();
  if (!firebaseAccessToken) {
    logger.error('No firebase token found');
    return screencastifyToken;
  }

  const shouldRefreshScreencastifyToken = shouldRefreshJwt(
    screencastifyToken,
    SECURITY_MARGIN,
  );
  if (!shouldRefreshScreencastifyToken) {
    return screencastifyToken;
  }

  const newScreencastifyToken = await exchangeScreencasitfyToken(
    firebaseAccessToken,
  ).catch((e) => {
    logger.error('Error on exchange screencastify token', e);
    return screencastifyToken;
  });
  if (!newScreencastifyToken) {
    logger.error('Error on refresh screencastify token');
    return screencastifyToken;
  }
  useAuthStore.getState().setScreencastifyToken(newScreencastifyToken);

  return newScreencastifyToken;
};

export const getFreshGoogleAccessToken = async (force = false) => {
  const { googleAccessToken } = useAuthStore.getState();
  const screencasitfyToken = await getFreshScreencastifyToken();
  if (!screencasitfyToken) {
    logger.error('No screencasitfy token token found');
    return googleAccessToken;
  }

  const shouldRefreshGoogleToken = await shouldRefreshGoogleAccessToken(
    googleAccessToken,
    SECURITY_MARGIN,
  );
  if (!shouldRefreshGoogleToken) {
    if (!force) return googleAccessToken;
    else
      logger.info('GoogleAccess token is still valid, but forcing new token');
  }

  const newGoogleAccessToken = await exchangeGoogleAccessToken(
    screencasitfyToken,
  ).catch((e) => {
    logger.error('Error on exchange google access token', e);
    return googleAccessToken;
  });
  if (!newGoogleAccessToken) {
    logger.error('Error on refresh GoogleAccess token');
    return googleAccessToken;
  }
  useAuthStore.getState().setGoogleAccessToken(newGoogleAccessToken);

  return newGoogleAccessToken;
};
