import { focusControllerTab } from '@castify/record-mv3/common';
import Alert from '@mui/material/Alert';
import Button from '@mui/material/Button';
import { PropsWithChildren, useEffect } from 'react';

interface Props {
  onClose: () => void;
}

export const AlertGoogleDriveFull = ({
  onClose,
  children,
}: PropsWithChildren<Props>) => {
  useEffect(() => {
    focusControllerTab();
  }, []);
  return (
    <Alert
      variant="filled"
      severity="error"
      color="error"
      sx={{
        alignItems: 'center',
        justifyContent: 'center',
        marginTop: '16px',
        '.MuiAlert-action': {
          margin: 0,
          padding: 0,
        },
      }}
      action={
        <Button
          color="inherit"
          size="small"
          onClick={onClose}
          sx={{ marginLeft: '64px' }}
        >
          Dismiss
        </Button>
      }
    >
      {children}
    </Alert>
  );
};
