import { useMutation } from '@tanstack/react-query';
import { useHttpClient } from './useHttpClient';
import { environment } from '@castify/record-mv3/environment';
import { AxiosError } from 'axios';
import axiosRetry from 'axios-retry';

export interface ContentDriveRootResponse {
  id: string;
  name: string;
}
export const DRIVE_FOLDER_ID = 'DRIVE_FOLDER_ID';

const getDriveRootFolderId = async (): Promise<string> => {
  const result = await chrome.storage.local.get(['DRIVE_FOLDER_ID']);
  return result.DRIVE_FOLDER_ID || '';
};

const setDriveRootFolderId = async (driveFolderId: string) => {
  return await chrome.storage.local.set({ DRIVE_FOLDER_ID: driveFolderId });
};

export function useContentDriveRoot() {
  const httpClient = useHttpClient();

  // Configure axios-retry
  axiosRetry(httpClient, {
    retries: 3,
    retryCondition: (error: AxiosError) => {
      // Retry on network errors or 5xx status codes
      return (
        axiosRetry.isNetworkOrIdempotentRequestError(error) ||
        error.response?.status === 403 ||
        error.response?.status === 401
      );
    },
  });

  return useMutation<string, Error, { ignoreCache?: boolean } | void>(
    async ({ ignoreCache } = {}) => {
      if (!ignoreCache) {
        const folderId = await getDriveRootFolderId();
        if (folderId) return folderId;
      }

      const result = await httpClient.get<ContentDriveRootResponse>(
        `${environment.contentServiceUrl}/drive-folder`,
      );
      setDriveRootFolderId(result.data?.id);
      return result.data?.id;
    },
  );
}
