import {
  getPartialRecordingSegments,
  getSortedRecordingSegments,
} from '@castify/record-mv3/recording-indexed-db';
import { memoize } from 'lodash';
import { IBrowserLogger, createBrowserLogger } from '@cfy/fe-monitoring';
import fixWebmDuration from 'webm-duration-fix';
import { processWithFfmpeg } from './processWithFfmpeg';

const TWO_GB = 2147483648; // 2GB in bytes
const PREVIEW_SEGMENTS = 2400; // 2400ms -> 20min -> Every segment has 0.5s aprox

interface RecordingData {
  url: string;
  blob: Blob;
}

const logger: IBrowserLogger = createBrowserLogger('recordingProcessor');

const combineSegments = (
  recordingSegments: { data: BlobPart }[],
  mimeType: string,
) => {
  const blobArray = recordingSegments.map((segment) => segment.data);
  return new Blob([...blobArray], { type: mimeType });
};

const processBlob = async (blob: Blob, recordingId: string) => {
  if (blob.size <= TWO_GB) {
    return await processWithFfmpeg(blob)
      .then((processedBlob) => {
        if (blob.size * 0.5 < processedBlob.size) return processedBlob;
        /* 
          If the processed blob size is less than or equal to half of the original blob size,
          we assume that the primary processing (processWithFfmpeg) failed for some reason
          (e.g., corrupt or incomplete data) and an alternative method
          (fixWebmDuration) is used to try and process or fix at least the metadata.
        */
        return fixWebmDuration(blob).catch((err) => {
          logger.error(
            'Error fixing WebmDuration after small processed size',
            err,
          );
          return blob;
        });
      })
      .catch(async (e: Error) => {
        logger.error(`Error processing Blob with ffmpeg: ${e}`);
        return fixWebmDuration(blob).catch((err) => {
          logger.error('Error fixing WebmDuration', err);
          return blob;
        });
      });
  } else {
    logger.info(`Blob is bigger than 2GB, fixing duration: ${recordingId}`);
    return fixWebmDuration(blob).catch((err) => {
      logger.error('Error fixing WebmDuration', err);
      return blob;
    });
  }
};

const createUrlFromBlob = (blob: Blob) => {
  const url = URL.createObjectURL(blob);
  logger.info(`Successfully created URL for processed Blob -> ${url}`);
  return url;
};

export const getRecordingData = memoize(
  async (
    recordingId: string,
    mimeType = 'video/webm; codecs="vp8, opus"',
  ): Promise<RecordingData> => {
    const recordingSegments = await getSortedRecordingSegments(recordingId);
    if (!recordingSegments || recordingSegments.length === 0) {
      return {
        url: '',
        blob: new Blob(),
      };
    }
    const condensedBlob = combineSegments(recordingSegments, mimeType);
    const processedBlob = await processBlob(condensedBlob, recordingId);
    if (!processedBlob) {
      logger.error(
        'Incomplete Blob - Processed Blob is incomplete or undefined.',
      );
      return {
        url: '',
        blob: new Blob(),
      };
    }
    return {
      url: createUrlFromBlob(processedBlob),
      blob: processedBlob,
    };
  },
);

export const getPreviewFromRecording = memoize(
  async (
    recordingId: string,
    mimeType = 'video/webm; codecs="vp8, opus"',
  ): Promise<RecordingData> => {
    const recordingSegments = await getPartialRecordingSegments(recordingId, {
      start: 0,
      end: PREVIEW_SEGMENTS,
    });
    if (!recordingSegments || recordingSegments.length === 0) {
      return {
        url: '',
        blob: new Blob(),
      };
    }
    const condensedBlob = combineSegments(recordingSegments, mimeType);
    const processedBlob = await processBlob(condensedBlob, recordingId);
    if (!processedBlob) {
      logger.error(
        'Preview: Incomplete Blob - Processed Blob is incomplete or undefined.',
      );
      return {
        url: '',
        blob: new Blob(),
      };
    }
    return {
      url: createUrlFromBlob(processedBlob),
      blob: processedBlob,
    };
  },
);
