import { StorageType, useHttpClient } from '@castify/record-mv3/common';
import { useMutation } from '@tanstack/react-query';
import { AxiosRequestHeaders } from 'axios';
import { useContentVideoExternalUrl } from './useContentVideoExternalUrl';
import { environment } from '@castify/record-mv3/environment';

export interface StartVideoPostParams {
  video: Blob;
  metadata: Record<string, unknown>;
  videoRegistryId: string;
  source: StorageType;
}

export function useStartVideoPostMutation() {
  const httpClient = useHttpClient();
  const { mutateAsync: GetContentVideoExternalUrl } =
    useContentVideoExternalUrl();

  return useMutation<string, Error, StartVideoPostParams>(
    async ({
      video,
      metadata,
      videoRegistryId,
      source,
    }: StartVideoPostParams): Promise<string> => {
      if (source === 'cloud') {
        // If source is 'cloud', use the current logic with GetContentVideoExternalUrl
        const videoUrl = await GetContentVideoExternalUrl({
          videoId: videoRegistryId,
          urlType: 'upload',
        });
        const headers: AxiosRequestHeaders = {
          'X-Upload-Content-Length': `${video.size}`,
          'X-Upload-Content-Type': (metadata.mimeType as string) ?? 'video/*',
          'x-goog-resumable': 'start',
        };

        const response = await httpClient.post<void>(videoUrl, null, {
          headers,
        });

        return response.headers.location;
      } else {
        // For other sources like 'drive', use the previous logic with googleDriveUploadV2
        const headers: AxiosRequestHeaders = {
          'X-Upload-Content-Length': `${video.size}`,
          'X-Upload-Content-Type': 'video/*',
        };

        const response = await httpClient.post<void>(
          `${environment.externalLinks.googleDriveUploadV2}/files?uploadType=resumable`,
          metadata,
          {
            headers,
          },
        );

        return response.headers.location;
      }
    },
  );
}
