import { IBrowserLogger, createBrowserLogger } from '@cfy/fe-monitoring';

const logger: IBrowserLogger = createBrowserLogger('RecorderHelpers');

interface GetUserMediaByStreamIdArgs {
  streamId: string;
  mediaSource: 'desktop' | 'tab';
  /**
   * The resolution constraint that we pass into `navigator.mediaDevices.getUserMedia()`.
   * If left `undefined`, `getUserMedia()` should not be called with a resolution constraint.
   *
   * Cases where it should be undefined:
   * 1. All `camera` recordings
   * 2. `desktop` recordings where `selectedResolution` is `OFF`.
   *
   * Cases where it should be defined:
   * 1. All `tab` recordings.
   * 2. `desktop` recordings where `selectedResolution` is *not* `OFF`.
   */
  resolution?: { width: number; height: number };
  frameRate: number;
  noiseSuppression: boolean;
}

// This getUserMedia call uses chromeMediaSource and is the only way to capture tab/desktop streams
export async function getUserMediaByStreamId({
  streamId,
  mediaSource,
  resolution,
  frameRate,
  noiseSuppression,
}: GetUserMediaByStreamIdArgs): Promise<MediaStream> {
  const resolutionConstraints = !resolution
    ? {}
    : {
        // Setting the min/max width/height effectively sets the exact w/h.
        // However, sometimes the resolution you provide is not the resolution
        // of the stream returned here. We have observed that this API can't
        // handle odd w/h values. Instead it does some scaling based on the
        // aspect ratio to make sure that the video is recorded at an even w/h.
        // To counter this, we resize the window beforehand in RecordingManager.
        minWidth: resolution.width,
        maxWidth: resolution.width,
        minHeight: resolution.height,
        maxHeight: resolution.height,
      };

  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: {
        mandatory: {
          maxFrameRate: frameRate,
          ...resolutionConstraints,
          chromeMediaSource: mediaSource,
          chromeMediaSourceId: streamId,
        },
      } as MediaTrackConstraints,
      audio: {
        mandatory: {
          noiseSuppression,
          chromeMediaSource: mediaSource,
          chromeMediaSourceId: streamId,
        },
      } as MediaTrackConstraints,
    });

    // Tab media stream consumes the tab audio, hooking it up to a
    // context destination (user's speakers) lets us still hear the tab
    if (mediaSource === 'tab') {
      const outputContext = new AudioContext();
      const sourceNode = outputContext.createMediaStreamSource(stream);
      sourceNode.connect(outputContext.destination);
    }
    return stream;
  } catch (error) {
    logger.error('Error getting user media stream by ID', { error: error });
    throw error;
  }
}

/*   This getUserMedia call uses does not use mandatory attribute like on getUserMediaByStreamId
and is for capturing webcam streams only
*/
const BASE_VIDEO_CONSTRAINTS = {
  frameRate: { ideal: 30, max: 60 },
  width: { min: 640, ideal: 1280, max: 1920 },
  height: { min: 360, ideal: 720, max: 1080 },
};

export async function getUserVideoByDeviceId(
  deviceId: string,
  noiseSuppression: boolean,
  useAudioDevice: boolean,
): Promise<MediaStream | undefined> {
  const audioConstraints = useAudioDevice ? { noiseSuppression } : undefined;
  const baseVideoConstraints = {
    ...BASE_VIDEO_CONSTRAINTS,
    deviceId,
  };

  return await navigator.mediaDevices
    .getUserMedia({
      video: {
        ...baseVideoConstraints,
        aspectRatio: { exact: 16 / 9 },
      },
      audio: audioConstraints,
    })
    .catch(async (error) => {
      logger.warn('Exact 16:9 not supported', { error });
      return await navigator.mediaDevices
        .getUserMedia({
          video: baseVideoConstraints,
          audio: audioConstraints,
        })
        .catch(async (fallbackError) => {
          logger.error('Error getting user video by device ID (fallback)', {
            fallbackError,
          });
          return undefined;
        });
    });
}

export async function getUserAudioByDeviceId(
  deviceId: string,
  noiseSuppression = false,
): Promise<MediaStream | undefined> {
  try {
    return await navigator.mediaDevices.getUserMedia({
      audio: {
        deviceId,
        noiseSuppression,
      },
    });
  } catch (error) {
    logger.error('Error getting user audio by device ID', { error: error });
    return;
  }
}

export async function navigateToTab(tabId: string | null) {
  if (!tabId) return;
  const tabs = await chrome.tabs.query({
    currentWindow: true,
  });

  for (const tab of tabs) {
    if (tabId && tab.id === parseInt(tabId)) {
      chrome.tabs.update(parseInt(tabId), {
        active: true,
      });
    }
  }
}
