import { useEffect, useRef, useState } from 'react';
import Button from '@mui/material/Button';
import Delete from '@mui/icons-material/Delete';
import {
  DeleteRecordingConfirmDialog,
  useControllerState,
} from '@castify/record-mv3/record-components';
import { useCreateVideoPlayer } from './hooks/useCreateVideoPlayer';
import styles from './LocalVideo.styles';
import Box from '@mui/material/Box';
import CircularProgress from '@mui/material/CircularProgress';
import Typography from '@mui/material/Typography';
import { IBrowserLogger, createBrowserLogger } from '@cfy/fe-monitoring';
import { openTabAndInjectLocalVideo } from '../controller/util/localVideoTabInjection';
import { observer } from 'mobx-react-lite';
import FormControlLabel from '@mui/material/FormControlLabel';
import Switch from '@mui/material/Switch';
import {
  StorageType,
  usePersonalSettingsQueryValueByKey,
  UserPersonalSettingKeys,
} from '@castify/record-mv3/common';
import { getPreviewFromRecording } from './utils/recordingProcessor';

interface LocalVideoProps {
  id: string;
  isLoading: boolean;
  progress: number;
  autoUpload: boolean;
  onUpload?: (id: string, blob: Blob | undefined) => void;
  onDownload: (blob: Blob | undefined) => void;
  onDelete: (id: string) => void;
}

export const LocalVideo = observer(
  ({
    id = '',
    isLoading = false,
    progress = 0,
    autoUpload = false,
    onUpload,
    // onDownload,
    onDelete,
  }: LocalVideoProps) => {
    const logger: IBrowserLogger = createBrowserLogger('Local Video');
    const { data: personalStorage } = usePersonalSettingsQueryValueByKey(
      UserPersonalSettingKeys.PersistentStorage,
    );

    const videoRef = useRef<HTMLVideoElement>(null);
    const [isDialogOpen, setIsDialogOpen] = useState(false);

    const [blobUrl, setBlobUrl] = useState('');
    const [blob, setBlob] = useState<Blob>();
    const [isBlobError, setBlobError] = useState(false);

    const { recordingStore } = useControllerState();
    const recording = recordingStore.getRecordingById(id);

    useEffect(() => {
      (async () => {
        try {
          const response = await getPreviewFromRecording(
            id,
            recording?.metadata.mimeType,
          );
          setBlobUrl(response.url);
          setBlob(response.blob);
          setBlobError(false);
        } catch (error) {
          logger.error(
            `Error getting recording data for video with recordingID ${id}.\n` +
              error,
          );
          setBlobError(true);
        }
      })();

      return () => {
        if (blobUrl) URL.revokeObjectURL(blobUrl);
      };
    }, [id]);

    useCreateVideoPlayer(videoRef, blobUrl);

    const handleDelete = () => {
      logger.info(`The user has manually deleted the video ${id}`);
      setIsDialogOpen(false);
      onDelete(id);
    };

    const videoRegistryId = recording?.metadata.videoRegistryId;
    const hasVideoRegistryId =
      typeof videoRegistryId === 'string' && videoRegistryId.length > 0;
    const isCloudRecording = personalStorage === StorageType.CLOUD;
    const storageName = isCloudRecording
      ? 'Screencastify Storage'
      : 'Google Drive';

    if (isBlobError) return <div>Error processing video {id}</div>;
    if (!blobUrl) return <div>Processing video {id}</div>;

    return (
      <section css={[styles.videoWrapper, styles.videoWrapperBorder]}>
        <video
          key={id}
          css={styles.video}
          ref={videoRef}
          id={`recording-to-upload-${id}`}
          controls
          controlsList="nodownload"
        />
        <section css={styles.buttonContainer}>
          <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            gap="16px"
          >
            <Button
              color="error"
              variant="outlined"
              onClick={() => setIsDialogOpen(true)}
              startIcon={<Delete />}
            >
              Delete
            </Button>
            {/* <Button
              color="secondary"
              variant="contained"
              onClick={() => onDownload(blob)}
            >
              Download
            </Button> */}
            <Button
              color="primary"
              variant="outlined"
              disabled={!hasVideoRegistryId}
              onClick={() =>
                videoRegistryId &&
                openTabAndInjectLocalVideo(videoRegistryId, blobUrl)
              }
            >
              View on Screencastify
            </Button>
            <FormControlLabel
              label={isLoading ? 'Uploading...' : `Upload to ${storageName}`}
              labelPlacement="start"
              sx={{ userSelect: 'none', gap: '8px', margin: 0 }}
              disabled={isLoading}
              control={
                <Switch
                  size="small"
                  checked={autoUpload}
                  onChange={() => recordingStore.toggleAutoUploadById(id)}
                />
              }
            />
          </Box>

          <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            gap="16px"
          >
            {isLoading && (
              <Box display="inline-flex" position="relative">
                <CircularProgress variant="determinate" value={progress} />
                <Box
                  display="flex"
                  justifyContent="center"
                  alignItems="center"
                  position="absolute"
                  sx={{ inset: 0 }}
                >
                  <Typography variant="caption" color="text.primary">
                    {`${progress}%`}
                  </Typography>
                </Box>
              </Box>
            )}
            {onUpload && (
              <Button
                color="primary"
                variant="contained"
                onClick={() => onUpload(id, blob)}
                disabled={isLoading}
              >
                Restart Upload
              </Button>
            )}
          </Box>
        </section>

        <DeleteRecordingConfirmDialog
          isOpen={isDialogOpen}
          onClose={() => setIsDialogOpen(false)}
          onClick={handleDelete}
        />
      </section>
    );
  },
);
