export const getBlobDuration = (blob: Blob): Promise<number> => {
  const tempVideoEl = document.createElement('video');

  const durationP: Promise<number> = new Promise((res, rej) => {
    tempVideoEl.addEventListener('loadedmetadata', () => {
      // Chrome bug: https://bugs.chromium.org/p/chromium/issues/detail?id=642012
      if (tempVideoEl.duration === Infinity) {
        tempVideoEl.currentTime = Number.MAX_SAFE_INTEGER;
        tempVideoEl.ontimeupdate = () => {
          tempVideoEl.ontimeupdate = null;
          res(tempVideoEl.duration);
          tempVideoEl.currentTime = 0;
        };
      } else res(tempVideoEl.duration);
    });
    tempVideoEl.onerror = () => rej('Error on Blob duration');
  });

  tempVideoEl.src = window.URL.createObjectURL(blob);

  return durationP;
};

interface BlobToFile {
  blob: Blob;
  name: string;
  type: string;
  lastModified: number;
}

export const blobToFile = ({
  blob,
  name,
  type,
  lastModified,
}: BlobToFile): File => {
  return new File([blob], name, {
    lastModified,
    type,
  });
};
