import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import CheckRoundedIcon from '@mui/icons-material/CheckRounded';

interface Props {
  charCount: number;
  maxChars: number;
  scriptContent: string;
  open: boolean;
  onClose: () => void;
  onScriptContentChange: (scriptContent: string) => void;
}

export const ExpandedScriptModal = ({
  charCount,
  maxChars,
  scriptContent,
  open,
  onClose,
  onScriptContentChange,
}: Props) => {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      fullWidth
      maxWidth="sm"
      PaperProps={{
        sx: {
          position: 'fixed',
          minWidth: '936px',
          width: '936px',
          borderRadius: '8px',
          maxHeight: 'none',
        },
      }}
    >
      <DialogTitle
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          p: '24px',
          pb: 0,
        }}
      >
        <Typography variant="h5" component="span" color="#212121">
          Edit Script
        </Typography>
        <Button
          onClick={onClose}
          startIcon={<CheckRoundedIcon />}
          variant="contained"
          sx={{ height: '36px', minHeight: '36px' }}
        >
          Done
        </Button>
      </DialogTitle>
      <DialogContent sx={{ mt: '16px', pb: '8px' }}>
        <TextField
          fullWidth
          multiline
          rows={24}
          placeholder="Type or paste your script here."
          value={scriptContent}
          inputProps={{ maxLength: maxChars }}
          onChange={(e) => onScriptContentChange(e.target.value)}
          variant="outlined"
          sx={{ mb: '4px' }}
        />
        <Typography
          variant="caption"
          color="text.secondary"
          sx={{ ml: '16px' }}
        >
          {charCount.toLocaleString('en-US')}/{maxChars.toLocaleString('en-US')}
        </Typography>
      </DialogContent>
    </Dialog>
  );
};
