import { useEffect, useState } from 'react';
import { getFflagNoCache } from './getFflagNoCache';

export const useUserManagementEnabledFflag = () => {
  const [isUserManagementEnabled, setIsUserManagementEnabled] = useState(false);

  useEffect(() => {
    const fetchFlag = async () => {
      const flagValue = await getFflagNoCache('isUserManagementEnabled');
      setIsUserManagementEnabled(flagValue);
    };

    fetchFlag();
  }, []);

  return isUserManagementEnabled;
};
