import { PropsWithChildren, useEffect } from 'react';
import { initPendo } from './pendo';
import { useAuthStore } from '@castify/record-mv3/common/stores';
import { PendoEventTracker } from './PendoEventTracker';
import { createBrowserLogger } from '@cfy/fe-monitoring';

const logger = createBrowserLogger('PendoProvider');

export function PendoProvider({ children }: PropsWithChildren) {
  const isAuth = useAuthStore((s) => s.isAuth);
  const userId = useAuthStore((s) => s.userId);
  const name = useAuthStore((s) => s.name);
  const email = useAuthStore((s) => s.email);

  useEffect(() => {
    const initializePendo = async () => {
      try {
        await initPendo({ visitorId: userId, name, email });
      } catch (err) {
        logger.error('Pendo init error:', err);
      }
    };

    if (!isAuth || !userId) return;
    initializePendo();
  }, [isAuth, userId]);

  return <PendoEventTracker>{children}</PendoEventTracker>;
}
