import { reaction } from 'mobx';
import { applySnapshot, getSnapshot } from 'mobx-state-tree';
import { useEffect } from 'react';
import { useControllerState } from '../../state/ControllerStateProvider';
import { ControllerStorageDriver } from './ControllerStorageDriver';

export const isSensitiveRecordingState = (recorderStatus?: string) =>
  ['recording', 'paused', 'stopped'].includes(String(recorderStatus));

export const useSyncedControllerState = () => {
  const controllerState = useControllerState();

  useEffect(() => {
    reaction(
      () => getSnapshot(controllerState.userState),
      (snapshot) => {
        // The MST type has a getter for isFreeUser,
        // but the type expects a property (that isn't needed)
        // @ts-expect-error key isFreeUser is missing
        ControllerStorageDriver.setUserState(snapshot);
      },
    );

    async function syncControllerState() {
      const localStorageState =
        await ControllerStorageDriver.getControllerState();
      const newSnapshot = {
        ...localStorageState,
        uploadingInProgress: controllerState.uploadingInProgress,
      };
      applySnapshot(controllerState, newSnapshot);
    }

    ControllerStorageDriver.createDisposableSubscription(syncControllerState);
  }, [controllerState]);

  return controllerState;
};
