import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import { ControlPanelHeader } from '../ControlPanelHeader';
import { popupStyles, regularStyles } from './Offline.styles';
import { trace } from '@opentelemetry/api';
import { NoWifi } from '../PopupImages/NoWifi.svg';

export const Offline: React.FC = () => {
  const isPopup = window.location.pathname === '/initializer.html';

  //TODO: remove example span once any mv3 involve user jouney is traced.
  const tracer = trace.getTracer('screencastify-mv3-ext');
  const span = tracer.startSpan('expensive-query');

  span.setAttribute('cfy.signin.isPopup', isPopup);
  span.end();

  return (
    <Box css={isPopup ? popupStyles.container : regularStyles.container}>
      <Box css={isPopup ? popupStyles.header : regularStyles.header}>
        <ControlPanelHeader />
      </Box>
      <Box css={isPopup ? popupStyles.body : regularStyles.body}>
        <Box css={isPopup ? popupStyles.content : regularStyles.content}>
          <NoWifi />
          <Typography variant="h4" mt="16px">
            You are offline
          </Typography>
          <Typography variant="body2">
            It looks like you are offline. Please check your connection.
          </Typography>
        </Box>
      </Box>
    </Box>
  );
};
