import { environment } from '@castify/record-mv3/environment';
import { useMutation } from '@tanstack/react-query';
import { StorageType, useHttpClient } from '@castify/record-mv3/common';
import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import axios from 'axios';
import { getExtensionBrowserType } from '@castify/record-mv3/environment';
import { DraftRecordingType } from '../util/getDraftRecordingType';
import { useSyncedControllerState } from '@castify/record-mv3/record-components';

export interface CreateDraftParams {
  source: StorageType;
  driveFileId: string;
  extensionVmpId: string;
  duration: number;
  creationTime: number;
  title: string;
  recordingType: DraftRecordingType;
  organizationId?: string;
}

export interface Draft {
  id: string;
}

export function useCreateDraftVideoMutation() {
  const logger: IBrowserLogger = createBrowserLogger(
    'CreateDraftVideoMutation',
  );
  const httpClient = useHttpClient();
  const {
    recordingSettings: { useWatermark },
  } = useSyncedControllerState();
  return useMutation<Draft, Error, CreateDraftParams>(
    async ({
      source,
      driveFileId,
      extensionVmpId,
      duration,
      creationTime,
      title,
      recordingType,
      organizationId,
    }: CreateDraftParams): Promise<Draft> => {
      const response = await httpClient.post<Draft>(
        `${environment.externalLinks.umbrellaServiceUrl}/registry`,
        {
          source,
          driveFileId,
          draft: true,
          privacy: 'user',
          privacyDomainList: [],
          collectViewAnalytics: true,
          title,
          recordingType,
          organizationId,
          videoMetadata: {
            mv3: chrome.runtime.getManifest().version,
            extensionType: getExtensionBrowserType(),
            extensionVmpId,
            duration,
            creationTime,
            hasWatermark: useWatermark,
          },
        },
      );
      return response.data;
    },
    {
      retry: 3,
      onError: (error) => {
        if (axios.isAxiosError(error)) {
          // Log the error response
          logger.error(
            `Error during draft video create: message: ${
              error.message
            }, response: ${JSON.stringify(error.response)}`,
          );
        } else {
          logger.error(
            `Error during draft video create: message: ${error.message}`,
          );
        }
      },
    },
  );
}
