import { environment } from '@castify/record-mv3/environment';
import { useHttpClient } from '@castify/record-mv3/common';
import { useMutation } from '@tanstack/react-query';
import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import axios from 'axios';

export interface GenerateIdsResponse {
  ids: string[];
  space: string;
  kind: string;
}

export function useGenerateGoogleDriveIdMutation() {
  const logger: IBrowserLogger = createBrowserLogger(
    'GenerateGoogleDriveIdMutation',
  );

  // const httpClient = mockHttpClient();
  const httpClient = useHttpClient();
  return useMutation<string, Error, void>(
    async (): Promise<string> => {
      const params = new URLSearchParams({ count: '1', space: 'drive' });
      const response = await httpClient.get<GenerateIdsResponse>(
        `${environment.externalLinks.googleDriveV3}/files/generateIds?${params}`,
      );
      return response.data.ids[0];
    },
    {
      onError: (error) => {
        if (axios.isAxiosError(error)) {
          // Log the error response
          logger.error(
            `Error during google id generation: message: ${
              error.message
            }, response: ${JSON.stringify(error.response?.data)}`,
          );
        } else {
          logger.error(
            `Error during google id generation: message: ${error.message}`,
          );
        }
      },
    },
  );
}
