const STORE_KEY = 'useAuthStore';

/** Gets the user's Firebase access token from local storage. */
export const getFirebaseAccessToken = async () => {
  return chrome.storage.local
    .get([STORE_KEY])
    .then((res) => {
      if (!res[STORE_KEY]) return '';
      return res[STORE_KEY]?.firebaseAccessToken;
    })
    .catch(() => '');
};
