import MenuItem from '@mui/material/MenuItem';
import Select from '@mui/material/Select';
import Typography from '@mui/material/Typography';
import { colors } from '@cfy/fe-common';
import {
  FrameRatePreset,
  FRAME_RATE_PRESETS,
} from '@castify/record-mv3/common';

interface Props {
  selectedFrameRate: FrameRatePreset;
  setSelectedFrameRate(value: FrameRatePreset): void;
}

export function MaxFrameRateSelect({
  selectedFrameRate,
  setSelectedFrameRate,
}: Props) {
  return (
    <Select
      fullWidth
      size="small"
      value={selectedFrameRate}
      onChange={(event) => {
        setSelectedFrameRate(event.target.value as FrameRatePreset);
      }}
    >
      <Typography p="8px 16px" color={colors.textSecondary}>
        Limit frame rate to:
      </Typography>
      {Object.entries(FRAME_RATE_PRESETS).map(([key, value]) => (
        <MenuItem key={key} value={key}>
          {value} FPS
        </MenuItem>
      ))}
    </Select>
  );
}
