import {
  CastifyLogo,
  extensionPageStyles,
  Offline,
  useIsOnline,
} from '@castify/record-mv3/common';
import { IBrowserLogger, createBrowserLogger } from '@cfy/fe-monitoring';
import Typography from '@mui/material/Typography';
import { observer } from 'mobx-react-lite';
import styles from './RecordingRecovery.styles';
import { downloadVideo } from '../controller/util/downloadVideo';
import { LocalVideo } from './LocalVideo';
import { useSyncedControllerState } from '@castify/record-mv3/record-components';
import { isSensitiveRecordingState } from '../controller/util/isSensitiveRecordingState';
import { PropsWithChildren } from 'react';

export const RecordingRecovery = observer(({ children }: PropsWithChildren) => {
  const logger: IBrowserLogger = createBrowserLogger('RecordingRecovery');
  const {
    recorderStatus,
    recordingInProgress,
    uploadingInProgress,
    recordingStore,
  } = useSyncedControllerState();

  const isOnline = useIsOnline();

  const handleDownload = (blob?: Blob) => {
    if (!blob) return;
    downloadVideo(blob);
  };

  const handleDelete = async (recordingId: string) => {
    logger.info('user clicked delete recording button on recovery page', {
      recordingId,
    });
    await recordingStore.removeRecording(recordingId);
  };

  if (!isOnline) return <Offline />;
  return (
    <div css={styles.wrapper}>
      <header css={extensionPageStyles.headerLogo}>
        <CastifyLogo />
      </header>
      <main id="content" css={styles.contentOuterContainer}>
        <section css={styles.contentInnerContainer}>
          <div css={extensionPageStyles.headingText}>
            <Typography align="center" variant="h1">
              Your locally saved videos
            </Typography>
          </div>

          <Typography
            css={extensionPageStyles.subHeadingText}
            align="center"
            variant="subtitle1"
          >
            Delete or upload locally saved videos.
          </Typography>
        </section>
        {children}

        {recordingStore
          .getRecordingList()
          .slice()
          .reverse()
          .map(({ id, autoUpload }) => {
            if (
              recordingInProgress.recordingId === id &&
              isSensitiveRecordingState(recorderStatus)
            )
              return null;
            const isUploading = id === uploadingInProgress.recordingId;
            return (
              <LocalVideo
                key={id}
                id={id}
                onDownload={handleDownload}
                onDelete={handleDelete}
                isLoading={isUploading}
                progress={isUploading ? uploadingInProgress.progress : 0}
                autoUpload={autoUpload}
              />
            );
          })}
      </main>
    </div>
  );
});
