import axios, { AxiosInstance } from 'axios';

import { environment } from '@castify/record-mv3/environment';

import { useAuthStore } from '../../stores';
import { getFreshGoogleAccessToken, getFreshScreencastifyToken } from '../auth';
import { APP_VERSION } from '../version';

export const useHttpClient = (): AxiosInstance => {
  const client = axios.create();

  client.interceptors.request.use(async (config) => {
    const { firebaseAccessToken, isAuth } = useAuthStore.getState();
    if (!firebaseAccessToken || !isAuth) {
      return config;
    }

    const { headers } = config;
    if (
      config.url?.startsWith(environment.externalLinks.googleDriveUploadV2) ||
      config.url?.startsWith(environment.externalLinks.googleDriveUploadV3) ||
      config.url?.startsWith(environment.externalLinks.googleDriveV3)
    ) {
      const googleAccessToken = await getFreshGoogleAccessToken();
      headers['Authorization'] ||= `Bearer ${googleAccessToken}`;
    } else if (
      config.url?.startsWith(environment.externalLinks.umbrellaServiceUrl)
    ) {
      headers['Authorization'] ||= `Bearer ${firebaseAccessToken}`;
    } else if (
      config.url?.startsWith(environment.featuresServiceUrl) ||
      config.url?.startsWith(environment.contentServiceUrl) ||
      config.url?.startsWith(environment.licensingServiceUrl) ||
      config.url?.startsWith(environment.userServiceUrl)
    ) {
      const screencastifyToken = await getFreshScreencastifyToken();
      headers['Authorization'] ||= `Bearer ${screencastifyToken}`;
      headers['x-cfy-request-origin'] ||= `extension`;
      headers['x-cfy-extension-version'] ||= `${APP_VERSION}`;
    }

    return config;
  });

  return client;
};
