import { useQuery } from '@tanstack/react-query';
import { getString, RemoteConfig } from 'firebase/remote-config';
import { Firestore } from 'firebase/firestore';
import { useRemoteConfig, useFirebase } from './Firebase';
import { refreshFirebaseToken } from '../auth';
import { useAuthStore } from '../../stores';
import { useHttpClient } from './useHttpClient';
import axios from 'axios';

export type VideoCountResponse = {
  videoCount: number;
};

export const isVideoCountResponse = (
  data?: unknown,
): data is VideoCountResponse =>
  data !== undefined &&
  data !== null &&
  typeof data === 'object' &&
  'videoCount' in data &&
  typeof (data as VideoCountResponse).videoCount === 'number';

export const USER_VIDEO_COUNT_QUERY_KEY = 'get-user-video-count';

export const getUserVideoCount = async (
  firestore: Firestore,
  userId: string,
  remoteConfig: RemoteConfig,
): Promise<VideoCountResponse> => {
  const firebaseAccessToken = useAuthStore.getState().firebaseAccessToken;

  const httpClient = useHttpClient();
  if (!firebaseAccessToken) {
    throw new Error('Firebase access token is missing');
  }

  const freeTierConfigValue = getString(remoteConfig, 'freeTierRestriction');
  const freeTierConfig = JSON.parse(freeTierConfigValue);

  if (!userId || !freeTierConfig) {
    throw new Error('Missing free tier remote config');
  }
  const { startDate, includeDeletedVideos } = freeTierConfig;

  const url = `https://firestore.googleapis.com/v1/projects/${firestore.app.options.projectId}/databases/(default)/documents:runAggregationQuery`;
  const requestBody = {
    structuredAggregationQuery: {
      aggregations: [
        {
          alias: 'videoCount',
          count: {},
        },
      ],
      structuredQuery: {
        from: [{ collectionId: 'videoRegistry' }],
        where: {
          compositeFilter: {
            op: 'AND',
            filters: [
              {
                fieldFilter: {
                  field: { fieldPath: 'userId' },
                  op: 'EQUAL',
                  value: { stringValue: userId },
                },
              },
              {
                fieldFilter: {
                  field: { fieldPath: 'deleted' },
                  op: includeDeletedVideos ? 'IN' : 'EQUAL',
                  value: includeDeletedVideos
                    ? {
                        arrayValue: {
                          values: [
                            { booleanValue: true },
                            { booleanValue: false },
                          ],
                        },
                      }
                    : { booleanValue: false },
                },
              },
              {
                fieldFilter: {
                  field: { fieldPath: 'createdAt' },
                  op: 'GREATER_THAN',
                  value: { timestampValue: new Date(startDate).toISOString() },
                },
              },
              {
                fieldFilter: {
                  field: { fieldPath: 'draft' },
                  op: 'EQUAL',
                  value: { booleanValue: false },
                },
              },
            ],
          },
        },
      },
    },
  };

  try {
    const response = await httpClient.post(url, requestBody, {
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${firebaseAccessToken}`,
      },
    });

    const data = response.data;
    const count = data[0]?.result?.aggregateFields?.videoCount?.integerValue;

    if (count === undefined) {
      throw new Error(
        'Failed to retrieve video count from response' + JSON.stringify(data),
      );
    }

    const videoCount = parseInt(count, 10);

    return {
      videoCount,
    };
  } catch (error) {
    if (axios.isAxiosError(error)) {
      const errorMessage = error.response
        ? `Error fetching video count: ${
            error.response.statusText
          }\n${JSON.stringify(error.response.data)}`
        : `Error fetching video count: ${error.message}`;
      throw new Error(errorMessage);
    } else {
      throw error;
    }
  }
};

export function useUserVideoCount({ enabled = true }: { enabled?: boolean }) {
  const { firestore } = useFirebase();
  const userId = useAuthStore.getState().userId;
  const remoteConfig = useRemoteConfig();

  return useQuery<VideoCountResponse, Error>({
    queryKey: [USER_VIDEO_COUNT_QUERY_KEY],
    queryFn: async () => {
      try {
        // Attempt to fetch the video count
        return await getUserVideoCount(firestore, userId!, remoteConfig);
      } catch (error) {
        if (error.response?.status === 401) {
          await refreshFirebaseToken();
          return await getUserVideoCount(firestore, userId!, remoteConfig);
        }
        throw error;
      }
    },
    enabled: enabled && !!userId,
    retry: (failureCount) => {
      if (failureCount < 3) {
        return true;
      }
      return false;
    },
    retryDelay: (attempt) => Math.min(1000 * 2 ** attempt, 30000), // Exponential backoff
    refetchOnWindowFocus: false,
  });
}
