import { create } from 'zustand';

export interface SyncStore<T> {
  loadStore: () => Promise<void>;
  set: (newState: Partial<T>) => void;
  get: () => T;
  isStoreLoaded: boolean;
}

interface SyncStoreOptions {
  storageType?: 'local' | 'session' | 'sync';
}

export const createSyncStore = <T>(
  storeName: string,
  initialState: T,
  options?: SyncStoreOptions,
) => {
  const { storageType = 'local' } = options ?? {};
  const storage = chrome.storage[storageType];

  const useStore = create<T & SyncStore<T>>((set, get) => {
    chrome.storage.onChanged.addListener((changes, namespace) => {
      if (namespace === storageType && changes[storeName]) {
        set({ ...changes[storeName].newValue, isStoreLoaded: true });
      }
    });

    return {
      ...initialState,
      isStoreLoaded: false,

      loadStore: async () => {
        const data = await storage.get(storeName);
        if (data[storeName]) {
          set({ ...data[storeName], isStoreLoaded: true });
        } else {
          set((state) => ({ ...state, isStoreLoaded: true }));
        }
      },

      get: () => get(),

      set: async (newState: Partial<T>) => {
        set((state) => {
          const updatedState = { ...state, ...newState };

          const serializableState = Object.fromEntries(
            Object.entries(updatedState).filter(
              ([, value]) => typeof value !== 'function',
            ),
          );
          storage.set({ [storeName]: serializableState });

          return updatedState;
        });
      },
    };
  });

  return useStore;
};
