export type Schema = number;

/** The target schema version for MV3 users */
export const SCHEMA: Schema = 4 as const;

/** An object representing a schema migration. */
export interface Migration {
  /** The current schema version. */
  from: Schema;
  /** The target schema version. */
  to: Schema;
  /** An async function that performs the data migration from -> to. */
  up: () => Promise<void>;
  /** An async function that performs the data migration to -> from. */
  down: () => Promise<void>;
}
