import { createBrowserLogger } from '@cfy/fe-monitoring';
import { FFmpeg } from '@ffmpeg/ffmpeg';

export class FFmpegProcessor {
  private ffmpeg = new FFmpeg();
  private isLoaded = false;
  private logger = createBrowserLogger('FFmpegProcessor');

  async load() {
    if (this.isLoaded) return;

    // download the ffmpeg.wasm package from https://app.unpkg.com/@ffmpeg/core@0.12.10/files/dist/esm
    await this.ffmpeg.load({
      coreURL: chrome.runtime.getURL('assets/ffmpeg/ffmpeg-core.js'),
      wasmURL: chrome.runtime.getURL('assets/ffmpeg/ffmpeg-core.wasm'),
    });
    this.isLoaded = true;
  }

  async processBlob(blob: Blob) {
    await this.load();

    const uniqueId = Date.now() + '-' + Math.floor(Math.random() * 10000);
    const inputName = `input_${uniqueId}.webm`;
    const outputName = `output_${uniqueId}.webm`;

    const arrayBuffer = await blob.arrayBuffer();
    const uint8Array = new Uint8Array(arrayBuffer);

    await this.ffmpeg.writeFile(inputName, uint8Array);
    await this.ffmpeg.exec(['-i', inputName, '-c', 'copy', outputName]);

    const data = await this.ffmpeg.readFile(outputName);
    const fixedBlob = new Blob([data], { type: 'video/webm' });

    await this.cleanup([inputName, outputName]);

    return fixedBlob;
  }

  private async cleanup(files: string[]) {
    for (const file of files) {
      try {
        await this.ffmpeg.readFile(file);
        await this.ffmpeg.deleteFile(file);
      } catch (err) {
        this.logger.warn(
          `File ${file} does not exist or cannot be deleted:`,
          err,
        );
      }
    }
  }
}
