import { createBrowserLogger } from '@cfy/fe-monitoring';
import { type PendoMsg } from './types';

const logger = createBrowserLogger('sendPendoEvent');

export const sendPendoEvent = ({ eventName, additionalData }: PendoMsg) => {
  try {
    chrome.runtime.sendMessage({
      type: 'PENDO_TRACK_EVENT',
      eventName,
      additionalData,
    });
  } catch (e) {
    logger.warn(`Error sending PENDO_TRACK_EVENT -> ${eventName}:`, e);
  }
};
