import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import { useEffect } from 'react';

const logger: IBrowserLogger = createBrowserLogger('useCreateVideoPlayer');
export const useCreateVideoPlayer = (
  videoRef: React.RefObject<HTMLVideoElement>,
  videoUrl: string | undefined,
) => {
  useEffect(() => {
    const makePlayer = () => {
      try {
        if (videoRef.current && videoUrl) {
          videoRef.current.src = videoUrl;
        }
      } catch (error) {
        logger.error(
          'Error occured during creation of video element on recording recovery page',
        );
      }
    };
    if (videoUrl) {
      makePlayer();
    }
  }, [videoUrl, videoRef]);
};
