import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogContentText from '@mui/material/DialogContentText';
import DialogTitle from '@mui/material/DialogTitle';
import styles from './RecordingConfirmDialog';

interface IDeleteConfirmDialogProps {
  isExtensionPopupView?: boolean;
  isOpen: boolean;
  onClose: () => void;
  onClick: () => void;
}

export const RestartRecordingConfirmDialog = ({
  isExtensionPopupView,
  isOpen,
  onClose,
  onClick,
}: IDeleteConfirmDialogProps) => {
  const DialogInnerContent = () => {
    return (
      <>
        <DialogTitle css={styles.title}>Are you sure?</DialogTitle>
        <DialogContent>
          <DialogContentText css={styles.contentText}>
            Restarting will permanently delete the current recording and
            automatically start a new one.
          </DialogContentText>
        </DialogContent>
        <DialogActions css={styles.actions}>
          <Button variant="outlined" onClick={onClose}>
            Cancel
          </Button>
          <Button variant="contained" color="error" onClick={onClick}>
            Yes, Restart
          </Button>
        </DialogActions>
      </>
    );
  };

  return isExtensionPopupView ? (
    <Dialog
      css={styles.container}
      open={isOpen}
      onClose={onClose}
      fullScreen
      hideBackdrop
      disablePortal
    >
      <DialogInnerContent />
    </Dialog>
  ) : (
    <Dialog open={isOpen} onClose={onClose}>
      <DialogInnerContent />
    </Dialog>
  );
};
