import { useEffect, useCallback, useState, SyntheticEvent } from 'react';
import {
  ControllerStorageDriver,
  IRecording,
  useSyncedControllerState,
} from '@castify/record-mv3/record-components';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { observer } from 'mobx-react-lite';
import { DesktopController } from './DesktopController';
import { TabController } from './TabController';
import { WebcamController } from './WebcamController';
import { RecordingRecovery } from '../recording-recovery/RecordingRecovery';
import styles from './Controller.styles';
import { useAutoUpload } from './hooks/useAutoUpload';
import { environment } from '@castify/record-mv3/environment';
import {
  injectLocalVideoToTab,
  openTabToLocalVideo,
} from './util/localVideoTabInjection';
import { focusControllerTab } from '@castify/record-mv3/common';
import { ErrorBoundary } from 'react-error-boundary';
import { RecordingRecoveryFallback } from './RecordingRecoveryFallback';
import { componentErrorHandler } from '@castify/record-mv3/error-handling';
import Snackbar, { SnackbarCloseReason } from '@mui/material/Snackbar';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';
import { useGenerateVideoId } from './hooks/useGenerateVideoId';
import ScreencasitfyIcon from '../assets/images/default-icon128.png';
import {
  getFreshGoogleAccessToken,
  refreshFirebaseToken,
} from '@castify/record-mv3/common/auth';
import {
  useAuthStore,
  useTeleprompterStore,
} from '@castify/record-mv3/common/stores';
import {
  StorageType,
  usePersonalSettingsQueryValueByKey,
  UserPersonalSettingKeys,
} from '@castify/record-mv3/common';
import { UploadError } from './util/uploadErrors';
import { GoogleDriveScopsDialog } from './dialogs/GoogleDriveScopsDialog';
import { AlertGoogleDriveFull } from './dialogs/AlertGoogleDriveFull';
import { getExtensionBrowserType } from '@castify/record-mv3/environment';
import { getPreviewFromRecording } from '../recording-recovery/utils/recordingProcessor';

interface notifyProps {
  title: string;
  message: string;
}

const chromeNotification = ({ title, message }: notifyProps) => {
  chrome.notifications.create({
    type: 'basic',
    iconUrl: ScreencasitfyIcon,
    title,
    message,
    priority: 2,
  });
};

export const Controller = observer(() => {
  const controllerState = useSyncedControllerState();
  const {
    recordingSettings,
    recorderStatus,
    recordingStore,
    recordingInProgress,
    userState,
  } = controllerState;
  const showTeleprompterModal = useTeleprompterStore(
    (s) => s.showTeleprompterModal,
  );
  const [showUploadMsg, setShowUploadMsg] = useState(false);
  const [snackbarMsg, setSnackbarMsg] = useState('');
  const [openDialog, setOpenDialog] = useState<string | null>(null);
  const [alertMsg, setAlertMsg] = useState('');
  const closeDialog = () => setOpenDialog(null);

  const { data: personalStorage } = usePersonalSettingsQueryValueByKey(
    UserPersonalSettingKeys.PersistentStorage,
  );
  const storageName =
    personalStorage === StorageType.CLOUD
      ? 'Screencastify Storage'
      : 'Google Drive';

  const currentVersion =
    chrome.runtime.getManifest().version_name + getExtensionBrowserType();
  const logger = new ServiceWorkerLogger(
    environment.logServiceUrl,
    getFirebaseAccessToken,
    {
      appName: 'Controller',
      buildId: currentVersion,
    },
  );

  const userId = useAuthStore.getState().userId;
  if (!userId) {
    return null;
  }

  const handleCloseSnackbar = (
    _: SyntheticEvent | Event,
    reason?: SnackbarCloseReason,
  ) => {
    if (reason === 'clickaway') return;
    setShowUploadMsg(false);
  };

  const handleUploadComplete = useCallback(() => {
    const successMsg = `Video uploaded to ${storageName}`;
    chromeNotification({
      title: 'Screencastify',
      message: successMsg,
    });
    setSnackbarMsg(successMsg);
    setShowUploadMsg(true);
    setAlertMsg('');
  }, [storageName]);

  const handleUploadError = useCallback(
    (type: string) => {
      if (type === UploadError.GENERIC) {
        const errorMsg = `Error uploading video to ${storageName}`;
        setSnackbarMsg(errorMsg);
        setShowUploadMsg(true);
      } else if (type === UploadError.GOOGLE_SCOPES) {
        setOpenDialog(type);
      } else if (type === UploadError.GOOGLE_FULL_STORAGE) {
        setAlertMsg('Upload has failed because Google Drive storage is full.');
      }
    },
    [setShowUploadMsg, setSnackbarMsg, storageName],
  );

  useAutoUpload({
    onUploadComplete: handleUploadComplete,
    onUploadError: handleUploadError,
  });

  const { mutateAsync: generateVideoIdAndCreateDraft } = useGenerateVideoId();

  const createOnComplete =
    (recording: IRecording) =>
    async (forceStopped = false) => {
      logger.info(
        `Finished recording. Recording ID: ${recording.id}. Force stopped: ${forceStopped}`,
      );

      if (recordingSettings.isLocalStorageMode) {
        logger.info(`Local Storage Mode - Video saved`);
        focusControllerTab();
        await recordingStore.saveRecoveryRecording();
        await chrome.tabs.reload();
        return;
      }

      // refresh token before start the uploading proceess
      await refreshFirebaseToken();

      let driveFileId: string | null = null;
      let videoRegistryId: string | null = null;
      let videoTitle = null;
      let metadata = null;
      let creationTime = null;
      let source = null;
      try {
        const data = await generateVideoIdAndCreateDraft(recording);
        videoRegistryId = data.videoId ?? null;
        metadata = data.metadata;
        videoTitle = metadata.title;
        creationTime = data.creationTime;
        driveFileId = data.driveFileId;
        source = data.source;

        if (typeof videoRegistryId !== 'string') {
          // Fall through to catch block
          throw Error(
            `Received unexpected data from call to create draft video for recording ${recording.id}.`,
          );
        }
        logger.info(
          `videoRegistry document with ID ${videoRegistryId} was generated for recording ${recording.id}`,
        );
      } catch (error) {
        logger.error(
          `Failed to generate draft videoRegistry document for recording ${recording.id}. ` +
            JSON.stringify(error),
        );
        await recordingStore.saveRecoveryRecording();

        return;
      }

      await recordingStore.removeRecoveryRecording();

      const recordingData = {
        id: recording.id,
        autoUpload: true,
        userId,
        orgId: userState.activeOrgId,
        metadata: {
          driveFileId,
          videoRegistryId: videoRegistryId,
          extensionVmpId: recording.id,
          creationTime,
          title: videoTitle,
          duration: recording.approximateDuration,
          mimeType: recording.mimeType,
          metadata,
          source,
        },
      };
      await recordingStore.addRecording(recordingData);
      logger.info(
        'Added the following recording to recordingStore: ' +
          JSON.stringify(recordingData, null, 2),
      );

      const { isProUser, userCastLengthLimit } = userState;

      const searchParams = new URLSearchParams();
      const isAutoStopAtLimit =
        recordingSettings.autoStopTime === userCastLengthLimit;

      if (!isProUser && forceStopped && isAutoStopAtLimit) {
        searchParams.append('tierRecordingLimitReached', 'true');
      }
      if (forceStopped) {
        searchParams.append(
          'recordingLimit',
          String(recordingSettings.autoStopTime),
        );
      }
      if (recording.isQuickStart) {
        searchParams.append('quickStart', 'true');
      }

      const vmpTab = await openTabToLocalVideo(videoRegistryId, searchParams);
      logger.info(
        `Controller on opened video ${videoRegistryId} ` +
          `in tab ${JSON.stringify(vmpTab, null, 2)}`,
      );

      await ControllerStorageDriver.resetRecorderStatus();
      await ControllerStorageDriver.resetRecordingInProgress();

      // On complete recording log
      logger.info(
        `State Tree Recording Complete: ${JSON.stringify(controllerState)})}`,
      );
    };

  const handleNewDataAvailable = async (
    duration: number,
    mimeType: string,
    title: string,
    orgId?: string,
  ) => {
    const creationTime = Date.now();
    await recordingStore.updateRecoveryRecording({
      id: recordingInProgress.recordingId,
      autoUpload: !recordingSettings.isLocalStorageMode,
      userId,
      orgId,
      metadata: {
        extensionVmpId: recordingInProgress.recordingId,
        creationTime,
        title,
        duration,
        mimeType,
      },
    });
  };

  const handleDelete = async () => {
    logger.info('User Deleted Recording');
    await recordingStore.removeRecoveryRecording();
  };

  const handleLocalVideoInjectionRequest = useCallback(
    async (
      message: {
        type: 'mv3:injectLocalVideo';
        data: { videoRegistryId: string };
      },
      sender: chrome.runtime.MessageSender,
      _sendResponse: (response: unknown) => void,
    ) => {
      if (
        !sender?.tab?.id ||
        !sender?.tab?.url?.startsWith(environment.externalLinks.manageVideoPage)
      ) {
        // Ignore messages from unexpected sources
        return;
      }

      if (message.type !== 'mv3:injectLocalVideo') {
        // Ignore messages we're not handling here
        return;
      }

      const videoRegistryId = message.data.videoRegistryId;
      const recording =
        recordingStore.getRecordingByVideoRegistryId(videoRegistryId);
      if (!recording) {
        logger.error(
          `Tab requested recording with unknown videoRegistryId.\n` +
            `Requested videoRegistryId: ${videoRegistryId}\n` +
            `recordingStore: ${JSON.stringify(recordingStore)}`,
        );
        return;
      }

      try {
        const { url: blobURL } = await getPreviewFromRecording(
          recording.id,
          recording.metadata.mimeType,
        );
        logger.info(
          `Successfully generated blob URL for video with recordingId ${recording.id}\n` +
            `Opening a new tab to ${sender.tab.url} and injecting blob URL ${blobURL}`,
        );
        injectLocalVideoToTab(sender.tab, blobURL);
      } catch (error) {
        logger.error(
          `Failed to generate blob URL for video with recordingId ${recording.id}\n` +
            error,
        );
      }
    },
    [recordingStore, logger],
  );

  useEffect(() => {
    chrome.runtime.onMessageExternal.addListener(
      handleLocalVideoInjectionRequest,
    );
    return () => {
      chrome.runtime.onMessageExternal.removeListener(
        handleLocalVideoInjectionRequest,
      );
    };
  }, [handleLocalVideoInjectionRequest]);

  const TypeSpecificController =
    recordingSettings.recordingType === 'tab'
      ? TabController
      : recordingSettings.recordingType === 'desktop'
      ? DesktopController
      : recordingSettings.recordingType === 'camera'
      ? WebcamController
      : () => null;

  const isCurrentlyRecordingOrPaused =
    recorderStatus === 'recording' || recorderStatus === 'paused';

  const isWebcamRecordingCountingIn =
    recorderStatus === 'counting-in' &&
    recordingSettings.recordingType === 'camera' &&
    recordingSettings.useCountIn;

  const useTeleprompter =
    recordingSettings.recordingType === 'camera' && showTeleprompterModal;

  const showWebcamLayout =
    isCurrentlyRecordingOrPaused ||
    isWebcamRecordingCountingIn ||
    useTeleprompter;

  return (
    <>
      <div css={!showWebcamLayout ? styles.hidden : null}>
        <TypeSpecificController
          createOnComplete={createOnComplete}
          onNewDataAvailable={handleNewDataAvailable}
          onDelete={handleDelete}
        />
      </div>
      {!showWebcamLayout && (
        <ErrorBoundary
          FallbackComponent={RecordingRecoveryFallback}
          onError={componentErrorHandler}
        >
          <RecordingRecovery>
            {alertMsg && (
              <AlertGoogleDriveFull onClose={() => setAlertMsg('')}>
                {alertMsg}
              </AlertGoogleDriveFull>
            )}
          </RecordingRecovery>
        </ErrorBoundary>
      )}

      <Snackbar
        open={showUploadMsg}
        autoHideDuration={5000}
        onClose={handleCloseSnackbar}
        message={snackbarMsg}
        anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
        action={
          <IconButton
            size="small"
            aria-label="close"
            color="inherit"
            onClick={handleCloseSnackbar}
          >
            <CloseIcon fontSize="small" />
          </IconButton>
        }
      />

      <GoogleDriveScopsDialog
        isOpen={openDialog === UploadError.GOOGLE_SCOPES}
        onTryAgain={() => {
          getFreshGoogleAccessToken(true);
          closeDialog();
        }}
      />
    </>
  );
});
