import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';
import { useMutation } from '@tanstack/react-query';
import { useHttpClient } from '@castify/record-mv3/common';
import axios from 'axios';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';

export interface UpdateDraftParams {
  videoRegistryId: string;
  driveFileId: string;
  draft: boolean;
}

export function useUpdateDraftVideoMutation() {
  const httpClient = useHttpClient();
  const currentVersion =
    chrome.runtime.getManifest().version_name + getExtensionBrowserType();
  const logger = new ServiceWorkerLogger(
    environment.logServiceUrl,
    getFirebaseAccessToken,
    {
      appName: 'useUpdateDraftVideoMutation',
      buildId: currentVersion,
    },
  );

  return useMutation<boolean, Error, UpdateDraftParams>(
    async ({
      videoRegistryId,
      driveFileId,
      draft,
    }: UpdateDraftParams): Promise<boolean> => {
      try {
        await httpClient.put<boolean>(
          `${environment.externalLinks.umbrellaServiceUrl}/registry/draftWithRegistry`,
          { videoRegistryId, driveFileId, draft },
        );
        return true;
      } catch (error) {
        if (error.response?.status === 409) {
          logger.info('update draft 409 skipping update draft');
          // already draft false
          return true;
        } else if (
          // for 404 and 503 errors try again
          axios.isAxiosError(error) &&
          (error.response?.status === 404 || error.response?.status === 503)
        ) {
          logger.warn('update draft failed first time due to 404 or 503');
          try {
            await httpClient.put<boolean>(
              `${environment.externalLinks.umbrellaServiceUrl}/registry/draftWithRegistry`,
              { videoRegistryId, driveFileId, draft },
            );
            return true;
          } catch (secondError) {
            if (
              axios.isAxiosError(secondError) &&
              secondError.response?.status === 404
            ) {
              return true; // Second 404 error, return true as success
            }
            throw secondError; // Any other error after retry, throw it
          }
        }
        throw error; // Non-404 errors or other issues are thrown
      }
    },
  );
}
