import { useEffect, useRef, useState } from 'react';
import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import TextField from '@mui/material/TextField';
import Button from '@mui/material/Button';
import Select from '@mui/material/Select';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import InputLabel from '@mui/material/InputLabel';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import CircularProgress from '@mui/material/CircularProgress';
import Divider from '@mui/material/Divider';
import Snackbar from '@mui/material/Snackbar';
import AutoAwesomeRoundedIcon from '@mui/icons-material/AutoAwesomeRounded';
import EditIcon from '@mui/icons-material/EditRounded';
import RefreshRoundedIcon from '@mui/icons-material/RefreshRounded';
import { ExpandedScriptModal } from './ExpandedScriptModal';
import { useTeleprompterStore } from '@castify/record-mv3/common/stores';
import {
  useHttpClient,
  useUserManagementEnabledFflag,
  openUpgradeUrl,
} from '@castify/record-mv3/common';
import { environment } from '@castify/record-mv3/environment';
import axios from 'axios';
import { createBrowserLogger, IBrowserLogger } from '@cfy/fe-monitoring';
import IconButton from '@mui/material/IconButton';
import CloseIcon from '@mui/icons-material/Close';
import { CloseTeleprompterDialog } from './CloseTeleprompterDialog';
import { colors } from '@cfy/fe-common';
import WorkspacePremiumRounded from '@mui/icons-material/WorkspacePremiumRounded';
import { useControllerState } from '@castify/record-mv3/record-components';

const minToMilliseconds = (min: number) => {
  return min * 60 * 1000;
};

const switchToFirstTab = () => {
  chrome.tabs.query({ currentWindow: true }, (tabs) => {
    if (tabs.length > 0) {
      const firstTab = tabs.at(1);
      if (!firstTab) return;
      chrome.tabs.update(firstTab.id!, { active: true });
    }
  });
};

interface Props {
  open: boolean;
  onStartRecording: () => void;
  onCancelScript: () => void;
}

interface VideoScriptResponse {
  content: string;
}

const MIN_TOPIC_CHARS = 25;
export const MAX_TOPIC_CHARS = 2000;
const MAX_SCRIPT_CHARS = 90_000;

const VIDEO_LENGTH_OPTIONS = [
  { label: '30 seconds', value: 0.5 },
  { label: '1 minute', value: 1 },
  { label: '2 minutes', value: 2 },
  { label: '3 minutes', value: 3 },
  { label: '4 minutes', value: 4 },
];

const LANGUAGE_OPTIONS = [
  { label: 'English', value: 'en' },
  { label: 'Spanish', value: 'es' },
];

const TONE_OPTIONS = [
  { label: 'Casual', value: 'casual' },
  { label: 'Energetic', value: 'energetic' },
  { label: 'Inspirational', value: 'inspirational' },
  { label: 'Instructional', value: 'instructional' },
  { label: 'Professional', value: 'professional' },
];

const logger: IBrowserLogger = createBrowserLogger('TeleprompterModal');

export const TeleprompterModal = ({
  open,
  onStartRecording,
  onCancelScript,
}: Props) => {
  const httpClient = useHttpClient();
  const { userState } = useControllerState();
  const isUserManagementEnabled = useUserManagementEnabledFflag();

  const handleUpgradeClick = () => {
    openUpgradeUrl(isUserManagementEnabled, userState.activeOrgId);
  };

  const isAIVideoScriptEnabled = useTeleprompterStore(
    (s) => s.isAIVideoScriptEnabled,
  );
  const scriptContent = useTeleprompterStore((s) => s.scriptContent);
  const setScriptContent = useTeleprompterStore((s) => s.setScriptContent);
  const videoTopic = useTeleprompterStore((s) => s.videoTopic);
  const setVideoTopic = useTeleprompterStore((s) => s.setVideoTopic);
  const [isTopicError, setIsTopicError] = useState(false);
  const [isScriptDirty, setIsScriptDirty] = useState(false);
  const [videoLength, setVideoLength] = useState(VIDEO_LENGTH_OPTIONS[2].value);
  const [language, setLanguage] = useState(LANGUAGE_OPTIONS[0].value);
  const [tone, setTone] = useState(TONE_OPTIONS[3].value);
  const [isLoading, setIsLoading] = useState(false);
  const [isError, setIsError] = useState(false);
  const [showExpandedScript, setShowExpandedScript] = useState(false);
  const [isCloseDialogOpen, setIsCloseDialogOpen] = useState(false);

  const abortControllerRef = useRef<AbortController | null>(null);

  const scriptCharCount = scriptContent.length;
  const isFormValid = videoTopic.trim() !== '';
  const isScriptEmpty = scriptContent.trim() === '';

  useEffect(() => {
    setIsScriptDirty(true);
  }, [videoTopic, videoLength, language, tone]);

  const handleGenerateScript = () => {
    setIsLoading(true);

    const controller = new AbortController();
    abortControllerRef.current = controller;

    httpClient
      .post<VideoScriptResponse>(
        `${environment.contentServiceUrl}/video-ai-scripts`,
        {
          videoTopic,
          tone,
          languageCode: language,
          length: minToMilliseconds(videoLength),
        },
        { signal: controller.signal },
      )
      .then(({ data }) => {
        setScriptContent(data.content);
        setIsScriptDirty(false);
        setIsLoading(false);
        setIsError(false);
      })
      .catch((err) => {
        if (axios.isCancel(err)) {
          logger.warn('Script generation request canceled.');
          return;
        }
        logger.error('Failed to generate script:', err);
        setIsLoading(false);
        setIsError(true);
      });
  };

  const handleCancel = () => {
    abortControllerRef.current?.abort();
    setIsLoading(false);
  };

  const handleClose = () => {
    switchToFirstTab();
    setIsCloseDialogOpen(false);
  };

  return (
    <>
      <Dialog
        open={open}
        fullWidth
        maxWidth="sm"
        PaperProps={{
          sx: {
            position: 'fixed',
            width: '432px',
            borderRadius: '8px',
          },
        }}
      >
        <DialogTitle
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: '8px',
            p: '24px',
            pb: 0,
          }}
        >
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}
          >
            <Typography
              variant="h5"
              component="span"
              color={colors.textPrimary}
            >
              Teleprompter
            </Typography>
            <IconButton
              onClick={() => setIsCloseDialogOpen(true)}
              aria-label="close"
            >
              <CloseIcon />
            </IconButton>
          </Box>
        </DialogTitle>

        <DialogContent sx={{ mt: '8px', pb: '0' }}>
          <Box display="flex" mb={2}>
            <AutoAwesomeRoundedIcon fontSize="small" color="secondary" />
            <Typography
              variant="body2"
              sx={{
                marginLeft: '8px',
              }}
            >
              AI Script Generator
            </Typography>
          </Box>
          <TextField
            fullWidth
            label="Describe video topic*"
            placeholder="e.g. video on trends shaping educational technology today"
            multiline
            rows={2}
            inputProps={{
              minLength: MIN_TOPIC_CHARS,
              maxLength: MAX_TOPIC_CHARS,
            }}
            InputLabelProps={{ shrink: true }}
            sx={{ mt: '8px', mb: '4px' }}
            disabled={isLoading || !isAIVideoScriptEnabled}
            value={videoTopic}
            onChange={(e) => {
              const { value } = e.target;
              setVideoTopic(value);
              setIsTopicError(
                value.length > 0 && value.length < MIN_TOPIC_CHARS,
              );
            }}
          />
          <Box
            sx={{
              display: 'flex',
              justifyContent: 'space-between',
            }}
          >
            <Typography
              variant="caption"
              color="text.secondary"
              sx={{ ml: '16px' }}
            >
              {videoTopic.length}/{MAX_TOPIC_CHARS}
            </Typography>
            {isTopicError && (
              <Typography variant="caption" color="error" sx={{ ml: '16px' }}>
                {isTopicError
                  ? `At least ${MIN_TOPIC_CHARS} characters required`
                  : ''}
              </Typography>
            )}
          </Box>

          <Box sx={{ display: 'flex', gap: 2, mb: '16px', mt: '16px' }}>
            <FormControl variant="outlined" size="small" sx={{ width: '50%' }}>
              <InputLabel>Select length</InputLabel>
              <Select
                value={videoLength}
                onChange={(e) => setVideoLength(Number(e.target.value))}
                label="Select length"
                disabled={isLoading || !isAIVideoScriptEnabled}
              >
                {VIDEO_LENGTH_OPTIONS.map(({ label, value }, i) => (
                  <MenuItem key={i} value={value}>
                    {label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <FormControl size="small" sx={{ width: '50%' }}>
              <InputLabel>Select language</InputLabel>
              <Select
                value={language}
                onChange={(e) => setLanguage(e.target.value)}
                label="Select language"
                disabled={isLoading || !isAIVideoScriptEnabled}
              >
                {LANGUAGE_OPTIONS.map(({ label, value }, i) => (
                  <MenuItem key={i} value={value}>
                    {label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>

          <FormControl fullWidth size="small" sx={{ mb: '16px' }}>
            <InputLabel>Select tone</InputLabel>
            <Select
              value={tone}
              onChange={(e) => setTone(e.target.value)}
              label="Select tone"
              disabled={isLoading || !isAIVideoScriptEnabled}
            >
              {TONE_OPTIONS.map(({ label, value }, i) => (
                <MenuItem key={i} value={value}>
                  {label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: '8px' }}>
            {isAIVideoScriptEnabled ? (
              <>
                <Button
                  onClick={handleGenerateScript}
                  variant="contained"
                  color="secondary"
                  startIcon={
                    isLoading ? (
                      <CircularProgress size="16px" color="inherit" />
                    ) : isScriptEmpty ? (
                      <AutoAwesomeRoundedIcon fontSize="small" />
                    ) : (
                      <RefreshRoundedIcon fontSize="small" />
                    )
                  }
                  disabled={
                    !isFormValid || isLoading || !isScriptDirty || isTopicError
                  }
                  sx={{ minWidth: '180px', height: '36px', minHeight: '36px' }}
                >
                  {isLoading
                    ? 'Generating Script...'
                    : isScriptEmpty
                    ? 'Generate Script'
                    : 'Delete & Re-Generate'}
                </Button>
                {isLoading && (
                  <Button
                    onClick={handleCancel}
                    variant="text"
                    color="info"
                    sx={{ height: '36px', minHeight: '36px' }}
                  >
                    Cancel
                  </Button>
                )}
              </>
            ) : (
              <Button
                variant="contained"
                startIcon={<WorkspacePremiumRounded />}
                sx={{
                  minWidth: '120px',
                  height: '36px',
                  minHeight: '36px',
                  background: 'linear-gradient(90deg, #F0B00C, #FF59B7)',
                }}
                onClick={handleUpgradeClick}
              >
                Upgrade
              </Button>
            )}
          </Box>

          <Divider sx={{ my: '16px' }} />

          <TextField
            fullWidth
            multiline
            disabled={isLoading}
            rows={7}
            placeholder={
              isAIVideoScriptEnabled
                ? 'The AI output will appear here. You can also type or paste your script here.'
                : 'Type or paste your script here.'
            }
            value={scriptContent}
            inputProps={{ maxLength: MAX_SCRIPT_CHARS }}
            onChange={(e) => {
              setScriptContent(e.target.value);
              setIsScriptDirty(true);
            }}
            variant="outlined"
            sx={{ mb: '4px' }}
          />
          <Typography
            variant="caption"
            color="text.secondary"
            sx={{ ml: '16px' }}
          >
            {scriptCharCount.toLocaleString('en-US')}/
            {MAX_SCRIPT_CHARS.toLocaleString('en-US')}
          </Typography>

          <Box
            sx={{
              display: 'flex',
              justifyContent: 'flex-end',
              alignItems: 'center',
              mb: '16px',
            }}
          >
            <Button
              startIcon={<EditIcon />}
              variant="text"
              onClick={() => setShowExpandedScript(true)}
              disabled={isLoading}
              sx={{ height: '36px', minHeight: '36px' }}
            >
              Edit Script
            </Button>
          </Box>
        </DialogContent>

        <DialogActions
          sx={{
            display: 'flex',
            flexDirection: 'column',
            p: '8px 24px',
          }}
        >
          <Button
            fullWidth
            variant="contained"
            disabled={isScriptEmpty || isLoading}
            sx={{ height: '48px', minHeight: '48px', mb: '16px' }}
            onClick={onStartRecording}
          >
            Start Recording
          </Button>

          <Button
            fullWidth
            variant="text"
            onClick={onCancelScript}
            color="info"
            sx={{ height: '48px', minHeight: '48px' }}
          >
            Record Without Script
          </Button>
        </DialogActions>
      </Dialog>

      <CloseTeleprompterDialog
        isOpen={isCloseDialogOpen}
        onClose={() => setIsCloseDialogOpen(false)}
        onConfirm={handleClose}
      />

      <ExpandedScriptModal
        open={showExpandedScript}
        onClose={() => setShowExpandedScript(false)}
        charCount={scriptCharCount}
        maxChars={MAX_SCRIPT_CHARS}
        scriptContent={scriptContent}
        onScriptContentChange={(newScriptContent) => {
          setScriptContent(newScriptContent);
          setIsScriptDirty(true);
        }}
      />

      <Snackbar
        open={isError}
        autoHideDuration={3000}
        onClose={() => setIsError(false)}
        message="There was an error. Please try again."
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
        sx={{
          '& .MuiSnackbarContent-root': {
            display: 'inline-block',
            minWidth: 'auto',
            borderRadius: '8px',
          },
        }}
      />
    </>
  );
};
