import { PropsWithChildren, useEffect } from 'react';
import { getPendoMsgFromEvent } from './getPendoMsgFromEvent';
import { createBrowserLogger } from '@cfy/fe-monitoring';
import { usePendoStore } from '@castify/record-mv3/common/stores';

interface PendoMessage {
  type: string;
  eventName?: string;
  additionalData?: Record<string, string | number>;
}

const logger = createBrowserLogger('PendoEventTracker');

export const PendoEventTracker = ({ children }: PropsWithChildren) => {
  const eventList = usePendoStore((s) => s.eventList);
  const resetEventList = usePendoStore((s) => s.resetEventList);

  // Pendo click event tracker
  useEffect(() => {
    const handleClick = (event: MouseEvent) => {
      const { eventName, additionalData } = getPendoMsgFromEvent(event);
      if (!eventName) return;
      if (!window.pendo?.isReady?.()) return;
      window.pendo.track?.(eventName, additionalData);
    };

    window.addEventListener('click', handleClick, true);
    return () => {
      window.removeEventListener('click', handleClick, true);
    };
  }, []);

  // Pendo external tracker
  useEffect(() => {
    const handleMessage = (message: PendoMessage) => {
      if (message.type !== 'PENDO_TRACK_EVENT') return;
      if (window.pendo?.isReady?.()) {
        if (!message.eventName) return;
        window.pendo.track(message.eventName, message.additionalData);
      } else {
        logger.warn('Pendo not ready, event discarded:', { message });
      }
    };

    chrome.runtime.onMessage.addListener(handleMessage);
    return () => {
      chrome.runtime.onMessage.removeListener(handleMessage);
    };
  }, []);

  // Pendo external stored event tracker
  useEffect(() => {
    if (eventList.length === 0) return;
    if (!window.pendo?.isReady?.()) return;
    eventList.forEach(({ eventName, additionalData = {} }) => {
      if (!eventName) return;
      window.pendo?.track?.(eventName, additionalData);
    });
    resetEventList();
  }, [eventList, resetEventList]);

  return <>{children}</>;
};
