import { useEffect, useRef } from 'react';

interface Props {
  stepSize?: number;
  interval?: number;
  animationDuration?: number;
  initialDelay?: number;
  disableAutoScroll?: boolean;
}

const DEFAULT_STEP_SIZE = 28;
const DEFAULT_INTERVAL = 2000;
const DEFAULT_ANIMATION_DURATION = 300;
const DEFAULT_INITIAL_DELAY = 6000;

export const useAutoScroll = ({
  stepSize = DEFAULT_STEP_SIZE,
  interval = DEFAULT_INTERVAL,
  animationDuration = DEFAULT_ANIMATION_DURATION,
  initialDelay = DEFAULT_INITIAL_DELAY,
  disableAutoScroll = false,
}: Props) => {
  const autoScrollRef = useRef<HTMLDivElement | null>(null);
  const animationRef = useRef<number | null>(null);
  const lastUpdateTime = useRef(performance.now());
  const initialDelayTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  const hasStarted = useRef(false);

  const timeoutDelay = interval - animationDuration;

  const animateScroll = (start: number, end: number, duration: number) => {
    const startTime = performance.now();
    const scrollContainer = autoScrollRef.current;
    if (!scrollContainer) return;

    const step = (currentTime: number) => {
      const elapsed = currentTime - startTime;
      const progress = Math.min(elapsed / duration, 1);
      scrollContainer.scrollTop = start + (end - start) * progress;

      if (progress < 1) {
        requestAnimationFrame(step);
      }
    };

    requestAnimationFrame(step);
  };

  const scrollStep = () => {
    const scrollContainer = autoScrollRef.current;
    if (!scrollContainer || disableAutoScroll) return;

    const now = performance.now();
    const deltaTime = now - lastUpdateTime.current;

    if (deltaTime >= interval) {
      const newScrollTop = scrollContainer.scrollTop + stepSize;
      animateScroll(scrollContainer.scrollTop, newScrollTop, animationDuration);
      lastUpdateTime.current = now;
    }

    animationRef.current = requestAnimationFrame(scrollStep);
  };

  const resetScroll = () => {
    const scrollContainer = autoScrollRef.current;
    if (!scrollContainer) return;

    scrollContainer.scrollTop = 0;

    if (animationRef.current) {
      cancelAnimationFrame(animationRef.current);
    }
    if (initialDelayTimeoutRef.current) {
      clearTimeout(initialDelayTimeoutRef.current);
    }

    lastUpdateTime.current = performance.now();
    hasStarted.current = false;

    if (!disableAutoScroll) {
      initialDelayTimeoutRef.current = setTimeout(() => {
        hasStarted.current = true;
        animationRef.current = requestAnimationFrame(scrollStep);
      }, initialDelay);
    }
  };

  useEffect(() => {
    if (disableAutoScroll) {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
      return;
    }

    const delay = !hasStarted.current ? initialDelay : timeoutDelay;
    hasStarted.current = true;

    initialDelayTimeoutRef.current = setTimeout(() => {
      animationRef.current = requestAnimationFrame(scrollStep);
    }, delay);

    return () => {
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
      if (initialDelayTimeoutRef.current) {
        clearTimeout(initialDelayTimeoutRef.current);
      }
    };
  }, [
    disableAutoScroll,
    stepSize,
    interval,
    animationDuration,
    timeoutDelay,
    initialDelay,
  ]);

  return {
    autoScrollRef,
    resetScroll,
  };
};
